  if (!template) throw new Error(`Gallery template not found: ${templateId}`);

  return buildRvfContainer({
    prompts: template.prompts,
    tools: template.tools,
    skills: template.skills,
    mcpTools: template.mcp_tools,  // ADR-129 P2: was silently dropped
  });
}

/**
 * AST Analyzer for Code Analysis
 *
 * Analyzes Abstract Syntax Trees for code understanding
 * and intelligent routing decisions.
 *
 * @module ast-analyzer
 */

export interface ASTAnalyzerConfig {
  maxFileSize: number;
  languages: string[];
  includeComments: boolean;
  extractTypes: boolean;
  maxDepth: number;
}

export interface ASTNode {
  type: string;
  name: string;
  startLine: number;
  endLine: number;
  children: ASTNode[];
  metadata?: Record<string, unknown>;
}

export interface ASTAnalysis {
  filePath: string;
  language: string;
  root: ASTNode;
  functions: ASTNode[];
  classes: ASTNode[];
  imports: string[];
  exports: string[];
  complexity: {
    cyclomatic: number;
    cognitive: number;
    loc: number;
    commentDensity: number;
  };
  timestamp: number;
  durationMs: number;
}

const DEFAULT_CONFIG: ASTAnalyzerConfig = {
  maxFileSize: 1024 * 1024,
  languages: ['typescript', 'javascript', 'python', 'rust', 'go'],
  includeComments: true,
  extractTypes: true,
  maxDepth: 20,
};

const LANGUAGE_PATTERNS: Record<string, RegExp[]> = {
  typescript: [/\.tsx?$/, /^import\s+.*from\s+['"]/, /:\s*(string|number|boolean|void)/],
  javascript: [/\.jsx?$/, /^(const|let|var)\s+\w+\s*=/, /module\.exports/],
  python: [/\.py$/, /^(def|class|import|from)\s+/, /^#!/],
  rust: [/\.rs$/, /^(fn|struct|impl|use)\s+/, /^(pub\s+)?mod\s+/],
  go: [/\.go$/, /^package\s+/, /^func\s+/],
};

export class ASTAnalyzer {
  private config: ASTAnalyzerConfig;
  private ruvectorEngine: unknown = null;
  private useNative = false;
  private analysisCache: Map<string, ASTAnalysis> = new Map();

  constructor(config: Partial<ASTAnalyzerConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  async initialize(): Promise<void> {
    try {
      // @ruvector/ast is optional - gracefully fallback if not installed
      const ruvector = await import('@ruvector/ast' as string).catch(() => null);
      if (ruvector) {
        this.ruvectorEngine = (ruvector as any).createASTAnalyzer?.(this.config);
        this.useNative = !!this.ruvectorEngine;
      }
    } catch {
      this.useNative = false;
    }
  }

  analyze(code: string, filePath: string = 'unknown'): ASTAnalysis {
    const startTime = performance.now();
    if (code.length > this.config.maxFileSize) {
      throw new Error(`File too large: ${code.length} bytes exceeds ${this.config.maxFileSize}`);
    }
    const cacheKey = this.getCacheKey(code, filePath);
    const cached = this.analysisCache.get(cacheKey);
    if (cached) return cached;
    const language = this.detectLanguage(code, filePath);
    const root = this.parseAST(code, language);
    const functions = this.extractFunctions(root);
    const classes = this.extractClasses(root);
    const imports = this.extractImports(code, language);
    const exports = this.extractExports(code, language);
    const complexity = this.calculateComplexity(code, root);
    const durationMs = performance.now() - startTime;
    const analysis: ASTAnalysis = {
      filePath, language, root, functions, classes, imports, exports,
      complexity, timestamp: Date.now(), durationMs,
    };
    this.analysisCache.set(cacheKey, analysis);
    return analysis;
  }

  getFunctionAtLine(analysis: ASTAnalysis, line: number): ASTNode | null {
    for (const func of analysis.functions) {
      if (line >= func.startLine && line <= func.endLine) return func;
    }
    return null;
  }

  getClassAtLine(analysis: ASTAnalysis, line: number): ASTNode | null {
    for (const cls of analysis.classes) {
      if (line >= cls.startLine && line <= cls.endLine) return cls;
    }
    return null;
  }

  getSymbols(analysis: ASTAnalysis): string[] {
    const symbols: string[] = [];
    for (const func of analysis.functions) symbols.push(func.name);
    for (const cls of analysis.classes) symbols.push(cls.name);
    return symbols;
  }

  getStats(): Record<string, number> {
    return { cacheSize: this.analysisCache.size, useNative: this.useNative ? 1 : 0 };
  }

  clearCache(): void { this.analysisCache.clear(); }

  private getCacheKey(code: string, filePath: string): string {
    let hash = 0;
    const str = filePath + code.substring(0, 1000);
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return `ast_${hash}_${code.length}`;
  }

  private detectLanguage(code: string, filePath: string): string {
    for (const [lang, patterns] of Object.entries(LANGUAGE_PATTERNS)) {
      for (const pattern of patterns) {
        if (pattern.test(filePath) || pattern.test(code)) return lang;
      }
    }
    return 'unknown';
  }

  private parseAST(code: string, language: string): ASTNode {
    const lines = code.split('\n');
    const root: ASTNode = { type: 'program', name: 'root', startLine: 1, endLine: lines.length, children: [] };
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const lineNum = i + 1;
      const funcMatch = this.matchFunction(line, language);
      if (funcMatch) {
        const funcNode: ASTNode = {
          type: 'function', name: funcMatch.name, startLine: lineNum,
          endLine: lineNum + this.findBlockEnd(lines, i), children: [],
          metadata: { params: funcMatch.params },
        };
        root.children.push(funcNode);
        continue;
      }
      const classMatch = this.matchClass(line, language);
      if (classMatch) {
        const classNode: ASTNode = {
          type: 'class', name: classMatch.name, startLine: lineNum,
          endLine: lineNum + this.findBlockEnd(lines, i), children: [],
          metadata: { extends: classMatch.extends },
        };
        root.children.push(classNode);
      }
    }
    return root;
  }

  private matchFunction(line: string, language: string): { name: string; params: string } | null {
    const patterns: Record<string, RegExp> = {
      typescript: /(?:export\s+)?(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/,
      javascript: /(?:export\s+)?(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/,
      python: /def\s+(\w+)\s*\(([^)]*)\)/,
      rust: /(?:pub\s+)?(?:async\s+)?fn\s+(\w+)\s*\(([^)]*)\)/,
      go: /func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(([^)]*)\)/,
    };
    const pattern = patterns[language];
    if (!pattern) return null;
    const match = line.match(pattern);
    if (match) return { name: match[1], params: match[2] || '' };
    const arrowMatch = line.match(/(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s+)?\([^)]*\)\s*=>/);
    if (arrowMatch) return { name: arrowMatch[1], params: '' };
    const methodMatch = line.match(/^\s*(?:async\s+)?(\w+)\s*\([^)]*\)\s*(?::\s*\w+)?\s*\{/);
    if (methodMatch && methodMatch[1] !== 'if' && methodMatch[1] !== 'while' && methodMatch[1] !== 'for') {
      return { name: methodMatch[1], params: '' };
    }
    return null;
  }

  private matchClass(line: string, language: string): { name: string; extends?: string } | null {
    const patterns: Record<string, RegExp> = {
      typescript: /(?:export\s+)?class\s+(\w+)(?:\s+extends\s+(\w+))?/,
      javascript: /(?:export\s+)?class\s+(\w+)(?:\s+extends\s+(\w+))?/,
      python: /class\s+(\w+)(?:\((\w+)\))?/,
      rust: /(?:pub\s+)?struct\s+(\w+)/,
      go: /type\s+(\w+)\s+struct/,
    };
    const pattern = patterns[language];
    if (!pattern) return null;
    const match = line.match(pattern);
    if (match) return { name: match[1], extends: match[2] };
    return null;
  }

  private findBlockEnd(lines: string[], startIdx: number): number {
    let depth = 0;
    let inBlock = false;
    for (let i = startIdx; i < lines.length; i++) {
      const line = lines[i];
      const opens = (line.match(/[\{]/g) || []).length;
      const closes = (line.match(/[\}]/g) || []).length;
      if (opens > 0) inBlock = true;
      depth += opens - closes;
      if (inBlock && depth <= 0) return i - startIdx;
    }
    return Math.min(50, lines.length - startIdx);
  }

  private extractFunctions(root: ASTNode): ASTNode[] {
    const functions: ASTNode[] = [];
    const visit = (node: ASTNode) => {
      if (node.type === 'function') functions.push(node);
      for (const child of node.children) visit(child);
    };
    visit(root);
    return functions;
  }

  private extractClasses(root: ASTNode): ASTNode[] {
    const classes: ASTNode[] = [];
    const visit = (node: ASTNode) => {
      if (node.type === 'class') classes.push(node);
      for (const child of node.children) visit(child);
    };
    visit(root);
    return classes;
  }

  private extractImports(code: string, language: string): string[] {
    const imports: string[] = [];
    const lines = code.split('\n');
    const patterns: Record<string, RegExp> = {
      typescript: /import\s+(?:.*\s+from\s+)?['"]([^'"]+)['"]/,
      javascript: /(?:import\s+.*from\s+|require\s*\(\s*)['"]([^'"]+)['"]/,
      python: /(?:from\s+(\S+)\s+import|import\s+(\S+))/,
      rust: /use\s+(\S+)/,
      go: /import\s+(?:\(\s*)?["']([^"']+)["']/,
    };
    const pattern = patterns[language];
    if (!pattern) return imports;
    for (const line of lines) {
      const match = line.match(pattern);
      if (match) imports.push(match[1] || match[2]);
    }
    return imports;
  }

  private extractExports(code: string, language: string): string[] {
    const exports: string[] = [];
    const lines = code.split('\n');
    for (const line of lines) {
      const exportMatch = line.match(/export\s+(?:default\s+)?(?:const|let|var|function|class|interface|type|enum)\s+(\w+)/);
      if (exportMatch) exports.push(exportMatch[1]);
      const namedExportMatch = line.match(/export\s*\{\s*([^}]+)\s*\}/);
      if (namedExportMatch) {
        const names = namedExportMatch[1].split(',').map(n => n.trim().split(/\s+as\s+/)[0]);
        exports.push(...names);
      }
    }
    return exports;
  }

  private calculateComplexity(code: string, root: ASTNode): ASTAnalysis['complexity'] {
    const lines = code.split('\n');
    const nonEmptyLines = lines.filter(l => l.trim().length > 0);
    const commentLines = lines.filter(l => /^\s*(\/\/|\/\*|\*|#)/.test(l));
    const decisionPoints = (code.match(/\b(if|else|for|while|switch|case|catch|&&|\|\||\?)\b/g) || []).length;
    const cyclomatic = decisionPoints + 1;
    let cognitive = 0;
    let nestingLevel = 0;
    for (const line of lines) {
      const opens = (line.match(/[\{]/g) || []).length;
      const closes = (line.match(/[\}]/g) || []).length;
      if (/\b(if|for|while|switch)\b/.test(line)) cognitive += 1 + nestingLevel;
      nestingLevel += opens - closes;
      nestingLevel = Math.max(0, nestingLevel);
    }
    return {
      cyclomatic, cognitive, loc: nonEmptyLines.length,
      commentDensity: lines.length > 0 ? commentLines.length / lines.length : 0,
    };
  }
}

export function createASTAnalyzer(config?: Partial<ASTAnalyzerConfig>): ASTAnalyzer {
  return new ASTAnalyzer(config);
}

/**
 * Deterministic Codemod Engine (ADR-143)
 *
 * Truly $0, no-LLM Tier-1 code transforms. Uses the TypeScript compiler API to
 * locate exact AST nodes, then applies formatting-preserving text-range edits to
 * the original source string (we never re-print the whole file, so comments and
 * formatting survive).
 *
 * Only intents that can be transformed *deterministically and safely* live here.
 * Intents that need inference or judgement (add-types, add-error-handling,
 * async-await) are intentionally NOT codemods — they route to a model. See
 * ADR-143 for the rationale.
 *
 * @module ruvector/codemods/engine
 */

import ts from 'typescript';
import { buildReassignmentResolver } from './scope-analysis.js';

export type CodemodIntent = 'var-to-const' | 'remove-console' | 'add-logging';

/** Intents this engine can apply deterministically with $0 cost. */
export const DETERMINISTIC_CODEMOD_INTENTS: readonly CodemodIntent[] = [
  'var-to-const',
  'remove-console',
  'add-logging',
] as const;

/** Intents recognised by the router but NOT safe as deterministic codemods. */
export const MODEL_ROUTED_INTENTS: readonly string[] = [
  'add-types',
  'add-error-handling',
  'async-await',
] as const;

export type CodemodLanguage = 'javascript' | 'typescript' | 'jsx' | 'tsx';

export interface CodemodResult {
  intent: CodemodIntent;
  success: boolean;
  /** true if the output differs from the input. */
  changed: boolean;
  output: string;
  /** number of discrete edit sites applied. */
  edits: number;
  language: CodemodLanguage;
  reason?: string;
}

interface TextEdit {
  start: number;
  end: number;
  replacement: string;
}

export function isDeterministicCodemod(intent: string): intent is CodemodIntent {
  return (DETERMINISTIC_CODEMOD_INTENTS as readonly string[]).includes(intent);
}

// ============================================================================
// Parsing & edit application
// ============================================================================

function scriptKind(language: CodemodLanguage): ts.ScriptKind {
  switch (language) {
    case 'typescript':
      return ts.ScriptKind.TS;
    case 'tsx':
      return ts.ScriptKind.TSX;
    case 'jsx':
      return ts.ScriptKind.JSX;
    default:
      return ts.ScriptKind.JS;
  }
}

function parse(code: string, language: CodemodLanguage): ts.SourceFile {
  return ts.createSourceFile(
    `codemod-input.${language}`,
    code,
    ts.ScriptTarget.Latest,
    /* setParentNodes */ true,
    scriptKind(language),
  );
}

function parseDiagnosticCount(sf: ts.SourceFile): number {
  // parseDiagnostics is internal but stable; guard so a missing field never throws.
  return (sf as unknown as { parseDiagnostics?: unknown[] }).parseDiagnostics?.length ?? 0;
}

/** Apply edits to the original source, right-to-left so offsets stay valid. */
function applyEdits(code: string, edits: TextEdit[]): string {
  const sorted = [...edits].sort((a, b) => b.start - a.start);
  let out = code;
  for (const e of sorted) {
    out = out.slice(0, e.start) + e.replacement + out.slice(e.end);
  }
  return out;
}

function lineStartOffset(code: string, pos: number): number {
  let i = pos;
  while (i > 0 && code[i - 1] !== '\n') i--;
  return i;
}

function leadingIndent(code: string, lineStart: number): string {
  let i = lineStart;
  while (i < code.length && (code[i] === ' ' || code[i] === '\t')) i++;
  return code.slice(lineStart, i);
}

// ============================================================================
// var-to-const  (scope-aware reassignment analysis — see scope-analysis.ts)
// ============================================================================

function isVarList(list: ts.VariableDeclarationList): boolean {
  return !(list.flags & (ts.NodeFlags.Let | ts.NodeFlags.Const));
}

function collectBindingNames(name: ts.BindingName, out: Set<string>): void {
  if (ts.isIdentifier(name)) {
    out.add(name.text);
    return;
  }
  for (const el of name.elements) {
    if (ts.isBindingElement(el)) collectBindingNames(el.name, out);
  }
}

function varToConstEdits(code: string, sf: ts.SourceFile): TextEdit[] {
  const resolver = buildReassignmentResolver(sf);
  const edits: TextEdit[] = [];

  const visit = (node: ts.Node): void => {
    if (ts.isVariableDeclarationList(node) && isVarList(node)) {
      const names = new Set<string>();
      for (const decl of node.declarations) collectBindingNames(decl.name, names);
      // `const` only when no declared binding is reassigned *within its own scope*.
      const anyReassigned = [...names].some((n) => resolver.isReassigned(n, node));
      const keyword = anyReassigned ? 'let' : 'const';

      // The `var` keyword is the first token of the declaration list.
      const start = node.getStart(sf);
      // Only rewrite when the literal text really is `var` (guards against odd trivia).
      if (code.slice(start, start + 3) === 'var') {
        edits.push({ start, end: start + 3, replacement: keyword });
      }
    }
    ts.forEachChild(node, visit);
  };

  visit(sf);
  return edits;
}

// ============================================================================
// remove-console
// ============================================================================

function rootIdentifier(expr: ts.Expression): ts.Identifier | undefined {
  let cur: ts.Expression = expr;
  while (ts.isPropertyAccessExpression(cur) || ts.isElementAccessExpression(cur)) {
    cur = cur.expression;
  }
  return ts.isIdentifier(cur) ? cur : undefined;
}

function isConsoleCallStatement(stmt: ts.Statement): boolean {
  if (!ts.isExpressionStatement(stmt)) return false;
  let expr: ts.Expression = stmt.expression;
  // unwrap `void console.log(x)` and awaited/comma forms defensively
  if (ts.isCallExpression(expr)) {
    const root = rootIdentifier(expr.expression);
    return !!root && root.text === 'console';
  }
  return false;
}

function removeConsoleEdits(code: string, sf: ts.SourceFile): TextEdit[] {
  const edits: TextEdit[] = [];

  const visit = (node: ts.Node): void => {
    if (isConsoleCallStatement(node as ts.Statement)) {
      const stmt = node as ts.Statement;
      const start = stmt.getStart(sf);
      const end = stmt.getEnd();
      const ls = lineStartOffset(code, start);
      const beforeIsBlank = code.slice(ls, start).trim() === '';

      // Is the rest of the line after the statement only whitespace?
      let lineEnd = end;
      while (lineEnd < code.length && code[lineEnd] !== '\n') lineEnd++;
      const afterIsBlank = code.slice(end, lineEnd).trim() === '';

      if (beforeIsBlank && afterIsBlank) {
        // Statement owns its line(s): drop the whole line incl. trailing newline.
        const dropEnd = lineEnd < code.length ? lineEnd + 1 : lineEnd;
        edits.push({ start: ls, end: dropEnd, replacement: '' });
      } else {
        // Inline with other code: remove just the statement, tidy one trailing space.
        let e = end;
        if (code[e] === ' ') e++;
        edits.push({ start, end: e, replacement: '' });
      }
    }
    ts.forEachChild(node, visit);
  };

  visit(sf);
  return edits;
}

// ============================================================================
// add-logging
// ============================================================================

type FunctionLike =
  | ts.FunctionDeclaration
  | ts.FunctionExpression
  | ts.ArrowFunction
  | ts.MethodDeclaration
  | ts.ConstructorDeclaration
  | ts.GetAccessorDeclaration
  | ts.SetAccessorDeclaration;

function isFunctionLikeWithBlock(node: ts.Node): node is FunctionLike {
  return (
    (ts.isFunctionDeclaration(node) ||
      ts.isFunctionExpression(node) ||
      ts.isArrowFunction(node) ||
      ts.isMethodDeclaration(node) ||
      ts.isConstructorDeclaration(node) ||
      ts.isGetAccessor(node) ||
      ts.isSetAccessor(node)) &&
    !!node.body &&
    ts.isBlock(node.body)
  );
}

function functionName(node: FunctionLike): string {
  if (ts.isConstructorDeclaration(node)) return 'constructor';
  if (
    (ts.isFunctionDeclaration(node) ||
      ts.isFunctionExpression(node) ||
      ts.isMethodDeclaration(node) ||
      ts.isGetAccessor(node) ||
      ts.isSetAccessor(node)) &&
    node.name &&
    (ts.isIdentifier(node.name) || ts.isStringLiteral(node.name))
  ) {
    return node.name.text;
  }
  // function expression / arrow assigned to a variable or property
  const parent = node.parent;
  if (parent && ts.isVariableDeclaration(parent) && ts.isIdentifier(parent.name)) return parent.name.text;
  if (parent && ts.isPropertyAssignment(parent) && ts.isIdentifier(parent.name)) return parent.name.text;
  return 'anonymous';
}

function alreadyLogsEntry(body: ts.Block, name: string): boolean {
  const first = body.statements[0];
  if (!first || !isConsoleCallStatement(first)) return false;
  const text = first.getText();
  return text.includes(`'${name} called'`) || text.includes(`"${name} called"`);
}

function addLoggingEdits(code: string, sf: ts.SourceFile): TextEdit[] {
  const edits: TextEdit[] = [];

  const visit = (node: ts.Node): void => {
    if (isFunctionLikeWithBlock(node)) {
      const body = node.body as ts.Block;
      const name = functionName(node);
      if (!alreadyLogsEntry(body, name)) {
        const braceOffset = body.getStart(sf); // position of '{'
        const headerLineStart = lineStartOffset(code, node.getStart(sf));
        const indent = leadingIndent(code, headerLineStart);
        const bodyIndent = indent + '  ';
        const insertion = `\n${bodyIndent}console.log(${JSON.stringify(`${name} called`)});`;
        edits.push({ start: braceOffset + 1, end: braceOffset + 1, replacement: insertion });
      }
    }
    ts.forEachChild(node, visit);
  };

  visit(sf);
  return edits;
}

// ============================================================================
// Public API
// ============================================================================

const TRANSFORMS: Record<CodemodIntent, (code: string, sf: ts.SourceFile) => TextEdit[]> = {
  'var-to-const': varToConstEdits,
  'remove-console': removeConsoleEdits,
  'add-logging': addLoggingEdits,
};

export interface ApplyCodemodOptions {
  language?: CodemodLanguage;
}

/**
 * Apply a deterministic codemod to a source string.
 *
 * Returns the transformed source plus metadata. Never throws on malformed input
 * — it reports `success: false` with a reason instead. Guarantees the output
 * does not introduce new parse errors (otherwise it returns the input unchanged).
 */
export function applyCodemod(
  intent: string,
  code: string,
  opts: ApplyCodemodOptions = {},
): CodemodResult {
  const language: CodemodLanguage = opts.language ?? 'typescript';

  if (!isDeterministicCodemod(intent)) {
    return {
      intent: intent as CodemodIntent,
      success: false,
      changed: false,
      output: code,
      edits: 0,
      language,
      reason: `"${intent}" is not a deterministic codemod — route it to a model (Tier 2/3).`,
    };
  }

  let sf: ts.SourceFile;
  try {
    sf = parse(code, language);
  } catch (err) {
    return {
      intent,
      success: false,
      changed: false,
      output: code,
      edits: 0,
      language,
      reason: `parse failed: ${(err as Error).message}`,
    };
  }

  const beforeDiagnostics = parseDiagnosticCount(sf);
  const edits = TRANSFORMS[intent](code, sf);

  if (edits.length === 0) {
    return { intent, success: true, changed: false, output: code, edits: 0, language };
  }

  const output = applyEdits(code, edits);

  // Safety net: never hand back source that parses worse than the input.
  const afterDiagnostics = parseDiagnosticCount(parse(output, language));
  if (afterDiagnostics > beforeDiagnostics) {
    return {
      intent,
      success: false,
      changed: false,
      output: code,
      edits: 0,
      language,
      reason: 'transform would introduce parse errors — aborted (input returned unchanged).',
    };
  }

  return { intent, success: true, changed: true, output, edits: edits.length, language };
}

/**
 * Scope-aware reassignment analysis for the `var-to-const` codemod (ADR-143).
 *
 * The naive version marks a `var` as reassigned if its name is assigned to
 * *anywhere* in the file. That is correct but over-conservative: a `var x` in
 * one function is forced to `let` just because an unrelated function also has
 * an `x = …`. This module resolves each assignment to the binding it actually
 * mutates (function-scope hoisting semantics), so a `var` becomes `const`
 * unless *its own* binding is reassigned.
 *
 * Soundness: resolution only ever attributes a reassignment to a scope that
 * actually hoists the name (i.e. genuinely declares that binding). It therefore
 * never marks a truly-reassigned binding as un-reassigned — so a `var` is only
 * promoted to `const` when it is provably never reassigned. Block-scoped
 * shadowing (let/const) is ignored for resolution, which can only make us *more*
 * conservative (fall back to `let`), never wrong.
 *
 * @module ruvector/codemods/scope-analysis
 */

import ts from 'typescript';

/** A scope is a function-like node or the SourceFile (the var-hoist boundaries). */
function isScopeNode(node: ts.Node): boolean {
  return (
    ts.isSourceFile(node) ||
    ts.isFunctionDeclaration(node) ||
    ts.isFunctionExpression(node) ||
    ts.isArrowFunction(node) ||
    ts.isMethodDeclaration(node) ||
    ts.isConstructorDeclaration(node) ||
    ts.isGetAccessorDeclaration(node) ||
    ts.isSetAccessorDeclaration(node)
  );
}

function enclosingScope(node: ts.Node): ts.Node {
  let cur: ts.Node | undefined = node.parent;
  while (cur && !isScopeNode(cur)) cur = cur.parent;
  return cur ?? node.getSourceFile();
}

function parentScope(scope: ts.Node): ts.Node | undefined {
  if (ts.isSourceFile(scope)) return undefined;
  return enclosingScope(scope);
}

function collectIdentifierNames(target: ts.Node, out: (name: string) => void): void {
  if (ts.isIdentifier(target)) {
    out(target.text);
    return;
  }
  // Destructuring assignment target (object/array literal on the LHS of `=`).
  ts.forEachChild(target, (child) => collectIdentifierNames(child, out));
}

const ASSIGNMENT_OPERATORS = new Set<ts.SyntaxKind>([
  ts.SyntaxKind.EqualsToken,
  ts.SyntaxKind.PlusEqualsToken,
  ts.SyntaxKind.MinusEqualsToken,
  ts.SyntaxKind.AsteriskEqualsToken,
  ts.SyntaxKind.AsteriskAsteriskEqualsToken,
  ts.SyntaxKind.SlashEqualsToken,
  ts.SyntaxKind.PercentEqualsToken,
  ts.SyntaxKind.LessThanLessThanEqualsToken,
  ts.SyntaxKind.GreaterThanGreaterThanEqualsToken,
  ts.SyntaxKind.GreaterThanGreaterThanGreaterThanEqualsToken,
  ts.SyntaxKind.AmpersandEqualsToken,
  ts.SyntaxKind.BarEqualsToken,
  ts.SyntaxKind.CaretEqualsToken,
  ts.SyntaxKind.BarBarEqualsToken,
  ts.SyntaxKind.AmpersandAmpersandEqualsToken,
  ts.SyntaxKind.QuestionQuestionEqualsToken,
]);

export interface ReassignmentResolver {
  /** True if the `var` binding declared by `declarationList` (for `name`) is reassigned within its scope. */
  isReassigned(name: string, declarationList: ts.VariableDeclarationList): boolean;
}

/**
 * Build a scope-aware resolver: which `var` bindings are actually reassigned.
 */
export function buildReassignmentResolver(sf: ts.SourceFile): ReassignmentResolver {
  // Names hoisted into each scope: var-declared names, function declarations,
  // and parameters. (Collected per scope, not crossing nested function scopes.)
  const hoisted = new Map<ts.Node, Set<string>>();
  const ensure = (scope: ts.Node): Set<string> => {
    let s = hoisted.get(scope);
    if (!s) { s = new Set(); hoisted.set(scope, s); }
    return s;
  };
  ensure(sf);

  const addBinding = (name: ts.BindingName, scope: ts.Node): void => {
    if (ts.isIdentifier(name)) {
      ensure(scope).add(name.text);
    } else {
      for (const el of name.elements) {
        if (ts.isBindingElement(el)) addBinding(el.name, scope);
      }
    }
  };

  // Pass 1 — record hoisted names per scope.
  const collectHoisted = (node: ts.Node): void => {
    if (isScopeNode(node) && !ts.isSourceFile(node)) {
      ensure(node);
      // Parameters belong to the function's own scope.
      const params = (node as ts.FunctionLikeDeclarationBase).parameters;
      if (params) for (const p of params) addBinding(p.name, node);
    }
    if (ts.isVariableDeclarationList(node) && !(node.flags & (ts.NodeFlags.Let | ts.NodeFlags.Const))) {
      const scope = enclosingScope(node); // var hoists to the nearest function/source scope
      for (const decl of node.declarations) addBinding(decl.name, scope);
    }
    if (ts.isFunctionDeclaration(node) && node.name) {
      ensure(enclosingScope(node)).add(node.name.text);
    }
    ts.forEachChild(node, collectHoisted);
  };
  collectHoisted(sf);

  const resolveScope = (name: string, from: ts.Node): ts.Node | undefined => {
    let scope: ts.Node | undefined = from;
    while (scope) {
      if (hoisted.get(scope)?.has(name)) return scope;
      scope = parentScope(scope);
    }
    return undefined;
  };

  // Pass 2 — attribute each reassignment to the binding (scope) it mutates.
  const reassigned = new Set<string>(); // key: `${scopeId}::${name}`
  const scopeIds = new Map<ts.Node, number>();
  let nextId = 0;
  const scopeId = (scope: ts.Node): number => {
    let id = scopeIds.get(scope);
    if (id === undefined) { id = nextId++; scopeIds.set(scope, id); }
    return id;
  };

  const markReassigned = (name: string, at: ts.Node): void => {
    const declScope = resolveScope(name, enclosingScope(at));
    if (declScope) reassigned.add(`${scopeId(declScope)}::${name}`);
  };

  const collectReassignments = (node: ts.Node): void => {
    if (ts.isBinaryExpression(node) && ASSIGNMENT_OPERATORS.has(node.operatorToken.kind)) {
      collectIdentifierNames(node.left, (n) => markReassigned(n, node));
    } else if (
      (ts.isPostfixUnaryExpression(node) || ts.isPrefixUnaryExpression(node)) &&
      (node.operator === ts.SyntaxKind.PlusPlusToken || node.operator === ts.SyntaxKind.MinusMinusToken) &&
      ts.isIdentifier(node.operand)
    ) {
      markReassigned(node.operand.text, node);
    }
    ts.forEachChild(node, collectReassignments);
  };
  collectReassignments(sf);

  return {
    isReassigned(name: string, declarationList: ts.VariableDeclarationList): boolean {
      const declScope = enclosingScope(declarationList);
      return reassigned.has(`${scopeId(declScope)}::${name}`);
    },
  };
}

/**
 * Coverage Router for Test Routing
 *
 * Optimizations:
 * - Async file I/O for non-blocking coverage loading
 * - TTL-based caching of coverage data
 * - Singleton router instance
 */

import * as pathMod from 'node:path';
import { existsSync } from 'node:fs';
import { readFile } from 'node:fs/promises';

// ============================================================================
// Caching for Performance
// ============================================================================

/**
 * Cache for coverage data (1 minute TTL)
 */
const coverageDataCache = new Map<string, { report: CoverageReport; timestamp: number }>();
const COVERAGE_CACHE_TTL_MS = 60 * 1000; // 1 minute

/**
 * Clear coverage cache
 */
export function clearCoverageCache(): void {
  coverageDataCache.clear();
}

/**
 * Get coverage cache stats
 */
export function getCoverageCacheStats(): { size: number } {
  return { size: coverageDataCache.size };
}

export interface CoverageRouterConfig {
  minCoverage: number;
  targetCoverage: number;
  incremental: boolean;
  coverageTypes: ('line' | 'branch' | 'function' | 'statement')[];
}

export interface FileCoverage {
  path: string;
  lineCoverage: number;
  branchCoverage: number;
  functionCoverage: number;
  statementCoverage: number;
  uncoveredLines: number[];
  totalLines: number;
  coveredLines: number;
}

export interface CoverageReport {
  overall: number;
  byType: { line: number; branch: number; function: number; statement: number };
  byFile: FileCoverage[];
  lowestCoverage: FileCoverage[];
  highestCoverage: FileCoverage[];
  uncoveredCritical: string[];
  timestamp: number;
}

export interface CoverageRouteResult {
  action: 'add-tests' | 'review-coverage' | 'skip' | 'prioritize';
  priority: number;
  targetFiles: string[];
  testTypes: ('unit' | 'integration' | 'e2e')[];
  gaps: Array<{ file: string; currentCoverage: number; targetCoverage: number; gap: number; suggestedTests: string[] }>;
  estimatedEffort: number;
  impactScore: number;
}

const DEFAULT_CONFIG: CoverageRouterConfig = {
  minCoverage: 70,
  targetCoverage: 85,
  incremental: true,
  coverageTypes: ['line', 'branch', 'function', 'statement'],
};

export class CoverageRouter {
  private config: CoverageRouterConfig;
  private ruvectorEngine: unknown = null;
  private useNative = false;
  private coverageHistory: CoverageReport[] = [];

  constructor(config: Partial<CoverageRouterConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  async initialize(): Promise<void> {
    try {
      // @ruvector/coverage is optional - gracefully fallback if not installed
      const ruvector = await import('@ruvector/coverage' as string).catch(() => null);
      if (ruvector) {
        this.ruvectorEngine = (ruvector as any).createCoverageRouter?.(this.config);
        this.useNative = !!this.ruvectorEngine;
      }
    } catch { this.useNative = false; }
  }

  parseCoverage(data: unknown, format: 'lcov' | 'istanbul' | 'cobertura' | 'json' = 'json'): CoverageReport {
    switch (format) {
      case 'lcov': return this.parseLcov(data as string);
      case 'istanbul': return this.parseIstanbul(data as Record<string, unknown>);
      case 'cobertura': return this.parseCobertura(data as string);
      default: return this.parseJson(data as Record<string, unknown>);
    }
  }

  route(coverage: CoverageReport, changedFiles?: string[]): CoverageRouteResult {
    const gaps = this.calculateGaps(coverage);
    const targetFiles = this.prioritizeFiles(coverage, changedFiles);
    const action = this.determineAction(coverage, gaps);
    const priority = this.calculatePriority(coverage, changedFiles);
    const testTypes = this.recommendTestTypes(gaps);
    const estimatedEffort = this.estimateEffort(gaps);
    const impactScore = this.calculateImpact(coverage, targetFiles);
    return { action, priority, targetFiles, testTypes, gaps, estimatedEffort, impactScore };
  }

  getTrend(): { direction: 'up' | 'down' | 'stable'; change: number } {
    if (this.coverageHistory.length < 2) return { direction: 'stable', change: 0 };
    const recent = this.coverageHistory[this.coverageHistory.length - 1];
    const previous = this.coverageHistory[this.coverageHistory.length - 2];
    const change = recent.overall - previous.overall;
    return { direction: change > 0.5 ? 'up' : change < -0.5 ? 'down' : 'stable', change };
  }

  addToHistory(report: CoverageReport): void {
    this.coverageHistory.push(report);
    if (this.coverageHistory.length > 10) this.coverageHistory.shift();
  }

  getStats(): Record<string, number | boolean> {
    return { useNative: this.useNative, historySize: this.coverageHistory.length, minCoverage: this.config.minCoverage, targetCoverage: this.config.targetCoverage };
  }

  private parseLcov(data: string): CoverageReport {
    const files: FileCoverage[] = [];
    let currentFile: Partial<FileCoverage> | null = null;
    const lines = data.split('\n');
    for (const line of lines) {
      if (line.startsWith('SF:')) {
        if (currentFile?.path) files.push(this.finalizeFileCoverage(currentFile));
        currentFile = { path: line.substring(3), uncoveredLines: [], totalLines: 0, coveredLines: 0 };
      } else if (line.startsWith('LF:')) { if (currentFile) currentFile.totalLines = parseInt(line.substring(3), 10); }
      else if (line.startsWith('LH:')) { if (currentFile) currentFile.coveredLines = parseInt(line.substring(3), 10); }
      else if (line.startsWith('DA:')) { const [lineNum, hits] = line.substring(3).split(',').map(Number); if (currentFile && hits === 0) currentFile.uncoveredLines?.push(lineNum); }
      else if (line === 'end_of_record') { if (currentFile?.path) files.push(this.finalizeFileCoverage(currentFile)); currentFile = null; }
    }
    return this.buildReport(files);
  }

  private parseIstanbul(data: Record<string, unknown>): CoverageReport {
    const files: FileCoverage[] = [];
    for (const [path, coverage] of Object.entries(data)) {
      const cov = coverage as Record<string, unknown>;
      const statements = cov.s as Record<string, number>;
      const functions = cov.f as Record<string, number>;
      const branches = cov.b as Record<string, number[]>;
      const statementCovered = Object.values(statements).filter(v => v > 0).length;
      const statementTotal = Object.values(statements).length;
      const functionCovered = Object.values(functions).filter(v => v > 0).length;
      const functionTotal = Object.values(functions).length;
      const branchCovered = Object.values(branches).flat().filter(v => v > 0).length;
      const branchTotal = Object.values(branches).flat().length;
      files.push({
        path, lineCoverage: statementTotal > 0 ? (statementCovered / statementTotal) * 100 : 100,
        branchCoverage: branchTotal > 0 ? (branchCovered / branchTotal) * 100 : 100,
        functionCoverage: functionTotal > 0 ? (functionCovered / functionTotal) * 100 : 100,
        statementCoverage: statementTotal > 0 ? (statementCovered / statementTotal) * 100 : 100,
        uncoveredLines: [], totalLines: statementTotal, coveredLines: statementCovered,
      });
    }
    return this.buildReport(files);
  }

  private parseCobertura(data: string): CoverageReport {
    const files: FileCoverage[] = [];
    const classMatches = data.matchAll(/<class[^>]*filename="([^"]+)"[^>]*line-rate="([^"]+)"[^>]*branch-rate="([^"]+)"[^>]*>/g);
    for (const match of classMatches) {
      files.push({
        path: match[1], lineCoverage: parseFloat(match[2]) * 100, branchCoverage: parseFloat(match[3]) * 100,
        functionCoverage: parseFloat(match[2]) * 100, statementCoverage: parseFloat(match[2]) * 100,
        uncoveredLines: [], totalLines: 0, coveredLines: 0,
      });
    }
    return this.buildReport(files);
  }

  private parseJson(data: Record<string, unknown>): CoverageReport {
    if (Array.isArray(data)) return this.buildReport(data as FileCoverage[]);
    const files: FileCoverage[] = [];
    for (const [path, coverage] of Object.entries(data)) {
      const cov = coverage as Partial<FileCoverage>;
      files.push({
        path, lineCoverage: cov.lineCoverage || 0, branchCoverage: cov.branchCoverage || 0,
        functionCoverage: cov.functionCoverage || 0, statementCoverage: cov.statementCoverage || 0,
        uncoveredLines: cov.uncoveredLines || [], totalLines: cov.totalLines || 0, coveredLines: cov.coveredLines || 0,
      });
    }
    return this.buildReport(files);
  }

  private finalizeFileCoverage(partial: Partial<FileCoverage>): FileCoverage {
    const lineCoverage = partial.totalLines && partial.totalLines > 0 ? (partial.coveredLines || 0) / partial.totalLines * 100 : 100;
    return { path: partial.path || 'unknown', lineCoverage, branchCoverage: lineCoverage, functionCoverage: lineCoverage, statementCoverage: lineCoverage, uncoveredLines: partial.uncoveredLines || [], totalLines: partial.totalLines || 0, coveredLines: partial.coveredLines || 0 };
  }

  private buildReport(files: FileCoverage[]): CoverageReport {
    const totalLines = files.reduce((sum, f) => sum + f.totalLines, 0);
    const coveredLines = files.reduce((sum, f) => sum + f.coveredLines, 0);
    const overall = totalLines > 0 ? (coveredLines / totalLines) * 100 : 100;
    const avgLine = files.length > 0 ? files.reduce((sum, f) => sum + f.lineCoverage, 0) / files.length : 100;
    const avgBranch = files.length > 0 ? files.reduce((sum, f) => sum + f.branchCoverage, 0) / files.length : 100;
    const avgFunction = files.length > 0 ? files.reduce((sum, f) => sum + f.functionCoverage, 0) / files.length : 100;
    const avgStatement = files.length > 0 ? files.reduce((sum, f) => sum + f.statementCoverage, 0) / files.length : 100;
    const sortedByLine = [...files].sort((a, b) => a.lineCoverage - b.lineCoverage);
    return { overall, byType: { line: avgLine, branch: avgBranch, function: avgFunction, statement: avgStatement }, byFile: files, lowestCoverage: sortedByLine.slice(0, 5), highestCoverage: sortedByLine.slice(-5).reverse(), uncoveredCritical: this.findCriticalUncovered(files), timestamp: Date.now() };
  }

  private findCriticalUncovered(files: FileCoverage[]): string[] {
    const critical: string[] = [];
    const criticalPatterns = [/auth/, /security/, /payment/, /core/, /main/, /index/];
    for (const file of files) {
      if (file.lineCoverage < this.config.minCoverage) {
        for (const pattern of criticalPatterns) { if (pattern.test(file.path)) { critical.push(file.path); break; } }
      }
    }
    return critical.slice(0, 10);
  }

  private calculateGaps(coverage: CoverageReport): CoverageRouteResult['gaps'] {
    const gaps: CoverageRouteResult['gaps'] = [];
    for (const file of coverage.byFile) {
      if (file.lineCoverage < this.config.targetCoverage) {
        const gap = this.config.targetCoverage - file.lineCoverage;
        gaps.push({ file: file.path, currentCoverage: file.lineCoverage, targetCoverage: this.config.targetCoverage, gap, suggestedTests: this.suggestTests(file) });
      }
    }
    return gaps.sort((a, b) => b.gap - a.gap).slice(0, 10);
  }

  private suggestTests(file: FileCoverage): string[] {
    const suggestions: string[] = [];
    if (file.uncoveredLines.length > 10) suggestions.push('Add unit tests for uncovered code paths');
    if (file.branchCoverage < 50) suggestions.push('Add branch coverage tests (if/else paths)');
    if (file.functionCoverage < 80) suggestions.push('Add tests for untested functions');
    if (/api|endpoint|route|handler/.test(file.path)) suggestions.push('Add integration tests for API endpoints');
    return suggestions.slice(0, 3);
  }

  private prioritizeFiles(coverage: CoverageReport, changedFiles?: string[]): string[] {
    let targetFiles = coverage.lowestCoverage.map(f => f.path);
    if (changedFiles && changedFiles.length > 0) {
      const changedWithLowCoverage = coverage.byFile.filter(f => changedFiles.some(cf => f.path.includes(cf))).filter(f => f.lineCoverage < this.config.targetCoverage).map(f => f.path);
      targetFiles = [...new Set([...changedWithLowCoverage, ...targetFiles])];
    }
    return targetFiles.slice(0, 10);
  }

  private determineAction(coverage: CoverageReport, gaps: CoverageRouteResult['gaps']): CoverageRouteResult['action'] {
    if (coverage.overall < this.config.minCoverage) return 'prioritize';
    if (gaps.length > 5) return 'add-tests';
    if (coverage.overall < this.config.targetCoverage) return 'review-coverage';
    return 'skip';
  }

  private calculatePriority(coverage: CoverageReport, changedFiles?: string[]): number {
    let priority = 5;
    if (coverage.overall < 50) priority += 4; else if (coverage.overall < 70) priority += 2; else if (coverage.overall < 85) priority += 1;
    priority += Math.min(3, coverage.uncoveredCritical.length);
    if (changedFiles && changedFiles.length > 0) {
      const changedLowCoverage = coverage.byFile.filter(f => changedFiles.some(cf => f.path.includes(cf))).filter(f => f.lineCoverage < this.config.minCoverage);
      priority += Math.min(2, changedLowCoverage.length);
    }
    return Math.min(10, priority);
  }

  private recommendTestTypes(gaps: CoverageRouteResult['gaps']): CoverageRouteResult['testTypes'] {
    const types: Set<'unit' | 'integration' | 'e2e'> = new Set(['unit']);
    for (const gap of gaps) {
      if (/api|endpoint|route|handler|service/.test(gap.file)) types.add('integration');
      if (/page|component|view|ui/.test(gap.file)) types.add('e2e');
    }
    return Array.from(types);
  }

  private estimateEffort(gaps: CoverageRouteResult['gaps']): number {
    let effort = 0;
    for (const gap of gaps) effort += (gap.gap / 10) * 0.5;
    return Math.round(effort * 10) / 10;
  }

  private calculateImpact(coverage: CoverageReport, targetFiles: string[]): number {
    const potentialGain = targetFiles.reduce((sum, file) => {
      const fileCov = coverage.byFile.find(f => f.path === file);
      return fileCov ? sum + (this.config.targetCoverage - fileCov.lineCoverage) : sum;
    }, 0);
    return Math.min(100, Math.round(potentialGain / targetFiles.length || 0));
  }
}

export function createCoverageRouter(config?: Partial<CoverageRouterConfig>): CoverageRouter {
  return new CoverageRouter(config);
}

