}

/**
 * Clear the diff cache (call when git state changes)
 */
export function clearDiffCache(): void {
  diffCache.clear();
}

/**
 * Assess risk for a single file
 */
export function assessFileRisk(file: DiffFile): FileRisk {
  const reasons: string[] = [];
  let score = 0;

  // Size-based risk
  const totalChanges = file.additions + file.deletions;
  if (totalChanges > 300) {
    score += 30;
    reasons.push('Large change size (>300 lines)');
  } else if (totalChanges > 100) {
    score += 15;
    reasons.push('Medium change size (>100 lines)');
  }

  // Path-based risk
  const lowerPath = file.path.toLowerCase();
  if (/security|auth|crypto|password/.test(lowerPath)) {
    score += 40;
    reasons.push('Security-sensitive file');
  }
  if (/payment|billing|transaction/.test(lowerPath)) {
    score += 35;
    reasons.push('Payment-related file');
  }
  if (/database|migration|schema/.test(lowerPath)) {
    score += 25;
    reasons.push('Database-related file');
  }
  if (/core|main|index/.test(lowerPath)) {
    score += 15;
    reasons.push('Core module');
  }
  if (/config|env|settings/.test(lowerPath)) {
    score += 20;
    reasons.push('Configuration file');
  }

  // Status-based risk
  if (file.status === 'deleted') {
    score += 10;
    reasons.push('File deleted');
  }

  // Binary file risk
  if (file.binary) {
    score += 5;
    reasons.push('Binary file');
  }

  let risk: RiskLevel = 'low';
  if (score >= 60) risk = 'critical';
  else if (score >= 40) risk = 'high';
  else if (score >= 20) risk = 'medium';

  return { file: file.path, risk, score: Math.min(100, score), reasons };
}

/**
 * Assess overall risk from files and file risks
 */
export function assessOverallRisk(files: DiffFile[], fileRisks: FileRisk[]): OverallRisk {
  const breakdown = { low: 0, medium: 0, high: 0, critical: 0 };
  let totalScore = 0;

  for (const fr of fileRisks) {
    breakdown[fr.risk]++;
    totalScore += fr.score;
  }

  const avgScore = fileRisks.length > 0 ? totalScore / fileRisks.length : 0;

  // Weight more heavily towards high/critical files
  const weightedScore = avgScore + (breakdown.critical * 15) + (breakdown.high * 10);

  let overall: RiskLevel = 'low';
  if (weightedScore >= 60 || breakdown.critical > 0) overall = 'critical';
  else if (weightedScore >= 40 || breakdown.high > 1) overall = 'high';
  else if (weightedScore >= 20 || breakdown.medium > 2) overall = 'medium';

  return { overall, score: Math.min(100, Math.round(weightedScore)), breakdown };
}

// Singleton classifier instance for reuse
let classifierInstance: DiffClassifier | null = null;

function getClassifier(): DiffClassifier {
  if (!classifierInstance) {
    classifierInstance = new DiffClassifier();
  }
  return classifierInstance;
}

/**
 * Classify a diff based on files (uses singleton classifier)
 */
export function classifyDiff(files: DiffFile[]): DiffClassification {
  const classifier = getClassifier();
  const fileDiffs: FileDiff[] = files.map(f => ({
    path: f.path,
    hunks: [],
    additions: f.additions,
    deletions: f.deletions,
    classification: classifier['classifyFile'](f.path, []),
  }));

  return classifier['computeOverallClassification'](fileDiffs);
}

/**
 * Suggest reviewers based on files and risks
 */
export function suggestReviewers(files: DiffFile[], fileRisks: FileRisk[]): string[] {
  const reviewers = new Set<string>();

  for (const file of files) {
    const lowerPath = file.path.toLowerCase();

    if (/security|auth|crypto/.test(lowerPath)) reviewers.add('security-team');
    if (/database|migration/.test(lowerPath)) reviewers.add('dba');
    if (/api|endpoint|route/.test(lowerPath)) reviewers.add('api-owner');
    if (/test|spec/.test(lowerPath)) reviewers.add('qa-engineer');
    if (/config|deploy|ci/.test(lowerPath)) reviewers.add('devops');
    if (/ui|component|style/.test(lowerPath)) reviewers.add('frontend-lead');
    if (/model|service|repository/.test(lowerPath)) reviewers.add('backend-lead');
  }

  // Add based on risk
  const hasHighRisk = fileRisks.some(fr => fr.risk === 'high' || fr.risk === 'critical');
  if (hasHighRisk) {
    reviewers.add('tech-lead');
    reviewers.add('senior-developer');
  }

  // Default reviewer
  if (reviewers.size === 0) {
    reviewers.add('developer');
  }

  return Array.from(reviewers).slice(0, 5);
}

// Analysis result cache
const analysisCache = new Map<string, { result: DiffAnalysisResult; timestamp: number }>();
const ANALYSIS_CACHE_TTL_MS = 3000; // 3 seconds

/**
 * Analyze a diff with full analysis (optimized with caching)
 */
export async function analyzeDiff(options: {
  ref?: string;
  useRuVector?: boolean;
  skipCache?: boolean;
}): Promise<DiffAnalysisResult> {
  const ref = options.ref || 'HEAD';

  // Check analysis cache (unless skipCache is true)
  if (!options.skipCache) {
    const cached = analysisCache.get(ref);
    if (cached && Date.now() - cached.timestamp < ANALYSIS_CACHE_TTL_MS) {
      return cached.result;
    }
  }

  // Use async git diff for non-blocking operation
  const files = await getGitDiffNumstatAsync(ref);

  // Parallel file risk assessment for large diffs
  const fileRisks = files.length > 20
    ? await Promise.all(files.map(f => Promise.resolve(assessFileRisk(f))))
    : files.map(assessFileRisk);

  const risk = assessOverallRisk(files, fileRisks);
  const classification = classifyDiff(files);
  const recommendedReviewers = suggestReviewers(files, fileRisks);

  const totalAdditions = files.reduce((sum, f) => sum + f.additions, 0);
  const totalDeletions = files.reduce((sum, f) => sum + f.deletions, 0);

  const result: DiffAnalysisResult = {
    ref,
    timestamp: Date.now(),
    files,
    risk,
    classification,
    summary: `${files.length} files changed (+${totalAdditions}/-${totalDeletions}), ${risk.overall} risk`,
    fileRisks,
    recommendedReviewers,
  };

  // Cache the result
  analysisCache.set(ref, { result, timestamp: Date.now() });

  return result;
}

/**
 * Synchronous version of analyzeDiff for backward compatibility
 */
export function analyzeDiffSync(options: {
  ref?: string;
  useRuVector?: boolean;
}): DiffAnalysisResult {
  const ref = options.ref || 'HEAD';

  // Check analysis cache
  const cached = analysisCache.get(ref);
  if (cached && Date.now() - cached.timestamp < ANALYSIS_CACHE_TTL_MS) {
    return cached.result;
  }

  const files = getGitDiffNumstat(ref);
  const fileRisks = files.map(assessFileRisk);
  const risk = assessOverallRisk(files, fileRisks);
  const classification = classifyDiff(files);
  const recommendedReviewers = suggestReviewers(files, fileRisks);

  const totalAdditions = files.reduce((sum, f) => sum + f.additions, 0);
  const totalDeletions = files.reduce((sum, f) => sum + f.deletions, 0);

  const result: DiffAnalysisResult = {
    ref,
    timestamp: Date.now(),
    files,
    risk,
    classification,
    summary: `${files.length} files changed (+${totalAdditions}/-${totalDeletions}), ${risk.overall} risk`,
    fileRisks,
    recommendedReviewers,
  };

  analysisCache.set(ref, { result, timestamp: Date.now() });
  return result;
}

/**
 * Clear all diff-related caches
 */
export function clearAllDiffCaches(): void {
  diffCache.clear();
  analysisCache.clear();
  classifierInstance?.clearCache();
}

/**
 * DiskANN Vector Search Backend
 *
 * SSD-friendly approximate nearest neighbor search using Vamana graph.
 * Falls back gracefully to HNSW (@ruvector/router VectorDb) or
 * pure-JS cosine similarity when DiskANN is unavailable.
 *
 * @module v3/cli/ruvector/diskann-backend
 */

// ===== Types =====

export interface DiskAnnConfig {
  dim: number;
  maxDegree?: number;
  buildBeam?: number;
  searchBeam?: number;
  alpha?: number;
  pqSubspaces?: number;
  storagePath?: string;
}

export interface SearchResult {
  id: string;
  distance: number;
  score: number; // Converted to similarity (1 / (1 + distance))
}

export type VectorBackend = 'diskann' | 'hnsw' | 'cosine-js';

// ===== Lazy loading =====

let diskannInstance: any = null;
let diskannAvailable: boolean | null = null;
let activeBackend: VectorBackend = 'cosine-js';

/**
 * Check if @ruvector/diskann is available
 */
export async function isDiskAnnAvailable(): Promise<boolean> {
  if (diskannAvailable !== null) return diskannAvailable;
  try {
    const { createRequire } = await import('module');
    const require2 = createRequire(import.meta.url);
    const mod = require2('@ruvector/diskann');
    diskannAvailable = typeof mod.DiskAnn === 'function';
    return diskannAvailable;
  } catch {
    diskannAvailable = false;
    return false;
  }
}

/**
 * Create or get a DiskANN index instance
 */
export async function getDiskAnnIndex(config: DiskAnnConfig): Promise<{
  index: any;
  backend: VectorBackend;
}> {
  if (diskannInstance) return { index: diskannInstance, backend: activeBackend };

  // Try DiskANN first
  if (await isDiskAnnAvailable()) {
    try {
      const { createRequire } = await import('module');
      const require2 = createRequire(import.meta.url);
      const { DiskAnn } = require2('@ruvector/diskann');

      const index = new DiskAnn({
        dim: config.dim,
        maxDegree: config.maxDegree ?? 64,
        buildBeam: config.buildBeam ?? 128,
        searchBeam: config.searchBeam ?? 64,
        alpha: config.alpha ?? 1.2,
        pqSubspaces: config.pqSubspaces ?? 0,
        storagePath: config.storagePath,
      });

      diskannInstance = index;
      activeBackend = 'diskann';
      return { index, backend: 'diskann' };
    } catch {
      // Fall through
    }
  }

  // Try HNSW (@ruvector/router VectorDb) as fallback
  try {
    const { createRequire } = await import('module');
    const require2 = createRequire(import.meta.url);
    const router = require2('@ruvector/router');
    if (router.VectorDb && router.DistanceMetric) {
      const index = new router.VectorDb({
        dimensions: config.dim,
        distanceMetric: router.DistanceMetric.Cosine,
        hnswM: 16,
        hnswEfConstruction: 200,
        hnswEfSearch: 100,
      });
      diskannInstance = index;
      activeBackend = 'hnsw';
      return { index, backend: 'hnsw' };
    }
  } catch {
    // Fall through
  }

  // Pure JS fallback
  const jsIndex = createJsFallbackIndex(config.dim);
  diskannInstance = jsIndex;
  activeBackend = 'cosine-js';
  return { index: jsIndex, backend: 'cosine-js' };
}

/**
 * Get the active backend name
 */
export function getActiveBackend(): VectorBackend {
  return activeBackend;
}

/**
 * Reset the index (for testing)
 */
export function resetIndex(): void {
  diskannInstance = null;
  diskannAvailable = null;
  activeBackend = 'cosine-js';
}

// ===== Unified search interface =====

/**
 * Insert a vector into the active backend
 */
export async function insertVector(
  id: string,
  vector: Float32Array,
  config: DiskAnnConfig = { dim: 384 }
): Promise<{ backend: VectorBackend }> {
  const { index, backend } = await getDiskAnnIndex(config);

  if (backend === 'diskann') {
    index.insert(id, vector);
  } else if (backend === 'hnsw') {
    index.insert(id, vector);
  } else {
    index.insert(id, vector);
  }

  return { backend };
}

/**
 * Build the index (required for DiskANN before search)
 */
export async function buildIndex(config: DiskAnnConfig = { dim: 384 }): Promise<void> {
  const { index, backend } = await getDiskAnnIndex(config);
  if (backend === 'diskann' && typeof index.build === 'function') {
    index.build();
  }
  // HNSW and JS fallback don't need explicit build
}

/**
 * Search for k nearest neighbors
 */
export async function searchVectors(
  query: Float32Array,
  k: number,
  config: DiskAnnConfig = { dim: 384 }
): Promise<SearchResult[]> {
  const { index, backend } = await getDiskAnnIndex(config);

  if (backend === 'diskann') {
    const results = index.search(query, k);
    return results.map((r: any) => ({
      id: r.id,
      distance: r.distance,
      score: 1 / (1 + r.distance), // Convert L2 distance to similarity
    }));
  }

  if (backend === 'hnsw') {
    const results = index.search(query, k);
    return results.map((r: any) => ({
      id: r.id,
      distance: r.score, // VectorDb returns distance as 'score'
      score: 1 / (1 + r.score),
    }));
  }

  // JS fallback
  return index.search(query, k);
}

// ===== Pure JS fallback =====

function createJsFallbackIndex(dim: number) {
  const vectors = new Map<string, Float32Array>();

  return {
    insert(id: string, vector: Float32Array): void {
      vectors.set(id, new Float32Array(vector));
    },
    search(query: Float32Array, k: number): SearchResult[] {
      const results: SearchResult[] = [];
      for (const [id, vec] of vectors) {
        let dot = 0, normQ = 0, normV = 0;
        for (let i = 0; i < dim; i++) {
          dot += query[i] * vec[i];
          normQ += query[i] * query[i];
          normV += vec[i] * vec[i];
        }
        const cosine = dot / (Math.sqrt(normQ) * Math.sqrt(normV) || 1);
        const distance = 1 - cosine;
        results.push({ id, distance, score: cosine });
      }
      return results.sort((a, b) => a.distance - b.distance).slice(0, k);
    },
    count(): number { return vectors.size; },
    delete(id: string): boolean { return vectors.delete(id); },
    build(): void { /* no-op */ },
  };
}

// ===== Benchmark utility =====

export interface BenchmarkResult {
  backend: VectorBackend;
  dim: number;
  vectorCount: number;
  insertTimeMs: number;
  buildTimeMs: number;
  searchTimeMs: number;
  searchesPerSecond: number;
  recall: number; // vs brute force
  memoryMB: number;
}

/**
 * Run a benchmark comparing available backends
 */
export async function benchmark(opts: {
  dim?: number;
  vectorCount?: number;
  k?: number;
  queries?: number;
} = {}): Promise<BenchmarkResult[]> {
  const dim = opts.dim ?? 384;
  const n = opts.vectorCount ?? 1000;
  const k = opts.k ?? 10;
  const queryCount = opts.queries ?? 100;
  const results: BenchmarkResult[] = [];

  // Generate random vectors
  const vectors: Array<[string, Float32Array]> = [];
  for (let i = 0; i < n; i++) {
    const v = new Float32Array(dim);
    for (let j = 0; j < dim; j++) v[j] = Math.random() * 2 - 1;
    // Normalize
    let norm = 0;
    for (let j = 0; j < dim; j++) norm += v[j] * v[j];
    norm = Math.sqrt(norm);
    for (let j = 0; j < dim; j++) v[j] /= norm;
    vectors.push([`vec-${i}`, v]);
  }

  // Generate query vectors
  const queries: Float32Array[] = [];
  for (let i = 0; i < queryCount; i++) {
    const q = new Float32Array(dim);
    for (let j = 0; j < dim; j++) q[j] = Math.random() * 2 - 1;
    let norm = 0;
    for (let j = 0; j < dim; j++) norm += q[j] * q[j];
    norm = Math.sqrt(norm);
    for (let j = 0; j < dim; j++) q[j] /= norm;
    queries.push(q);
  }

  // Brute force ground truth
  function bruteForceSearch(query: Float32Array): string[] {
    const scores: Array<{ id: string; dist: number }> = [];
    for (const [id, vec] of vectors) {
      let dist = 0;
      for (let j = 0; j < dim; j++) {
        const d = query[j] - vec[j];
        dist += d * d;
      }
      scores.push({ id, dist });
    }
    scores.sort((a, b) => a.dist - b.dist);
    return scores.slice(0, k).map(s => s.id);
  }

  const groundTruth = queries.map(q => bruteForceSearch(q));

  // Test each available backend
  for (const backendName of ['diskann', 'hnsw', 'cosine-js'] as VectorBackend[]) {
    resetIndex();

    try {
      let index: any;
      const memBefore = process.memoryUsage().heapUsed;

      if (backendName === 'diskann') {
        if (!(await isDiskAnnAvailable())) continue;
        const { createRequire } = await import('module');
        const require2 = createRequire(import.meta.url);
        const { DiskAnn } = require2('@ruvector/diskann');
        index = new DiskAnn({ dim, maxDegree: 64, buildBeam: 128, searchBeam: 64 });
      } else if (backendName === 'hnsw') {
        try {
          const { createRequire } = await import('module');
          const require2 = createRequire(import.meta.url);
          const router = require2('@ruvector/router');
          if (!router.VectorDb) continue;
          index = new router.VectorDb({ dimensions: dim, distanceMetric: router.DistanceMetric.Cosine });
        } catch { continue; }
      } else {
        index = createJsFallbackIndex(dim);
      }

      // Insert
      const insertStart = performance.now();
      for (const [id, vec] of vectors) {
        index.insert(id, vec);
      }
      const insertTime = performance.now() - insertStart;

      // Build
      const buildStart = performance.now();
      if (typeof index.build === 'function') index.build();
      const buildTime = performance.now() - buildStart;

      // Search
      const searchStart = performance.now();
      const searchResults: string[][] = [];
      for (const q of queries) {
        const r = index.search(q, k);
        searchResults.push(r.map((x: any) => x.id));
      }
      const searchTime = performance.now() - searchStart;

      // Recall vs ground truth
      let totalRecall = 0;
      for (let i = 0; i < queryCount; i++) {
        const truth = new Set(groundTruth[i]);
        const found = searchResults[i].filter(id => truth.has(id)).length;
        totalRecall += found / k;
      }
      const recall = totalRecall / queryCount;

      const memAfter = process.memoryUsage().heapUsed;

      results.push({
        backend: backendName,
        dim,
        vectorCount: n,
        insertTimeMs: Math.round(insertTime * 100) / 100,
        buildTimeMs: Math.round(buildTime * 100) / 100,
        searchTimeMs: Math.round(searchTime * 100) / 100,
        searchesPerSecond: Math.round(queryCount / (searchTime / 1000)),
        recall: Math.round(recall * 1000) / 1000,
        memoryMB: Math.round((memAfter - memBefore) / 1024 / 1024 * 100) / 100,
      });
    } catch {
      // Backend failed, skip
    }
  }

  resetIndex();
  return results;
}

/**
 * Enhanced Model Router with Agent Booster AST Integration
 *
 * Implements ADR-026: 3-tier intelligent model routing:
 * - Tier 1: Agent Booster (WASM) - <1ms, $0 for simple transforms
 * - Tier 2: Haiku - ~500ms for low complexity
 * - Tier 3: Sonnet/Opus - 2-5s for high complexity
 *
 * @module enhanced-model-router
 */

import { existsSync, readFileSync, writeFileSync } from 'fs';
import { extname, isAbsolute, resolve as resolvePath } from 'path';
import { ClaudeModel, getModelRouter, ModelRouter, ModelRoutingResult } from './model-router.js';
import { applyCodemod, isDeterministicCodemod, type CodemodLanguage } from './codemods/engine.js';

/** Map a file path to the codemod engine's language, falling back to a hint. */
function codemodLanguageFor(filePath: string, fallback?: string): CodemodLanguage {
  const ext = extname(filePath).toLowerCase();
  if (ext === '.tsx') return 'tsx';
  if (ext === '.jsx') return 'jsx';
  if (ext === '.ts' || ext === '.mts' || ext === '.cts') return 'typescript';
  if (ext === '.js' || ext === '.mjs' || ext === '.cjs') return 'javascript';
  return fallback === 'typescript' ? 'typescript' : 'javascript';
}

// ============================================================================
// Types
// ============================================================================

/**
 * Code editing intent types that Agent Booster can handle
 */
export type EditIntentType =
  | 'var-to-const'
  | 'add-types'
  | 'add-error-handling'
  | 'async-await'
  | 'add-logging'
  | 'remove-console';

/**
 * Detected edit intent from task analysis
 */
export interface EditIntent {
  type: EditIntentType;
  confidence: number;
  filePath?: string;
  language?: string;
  description: string;
}

/**
 * Enhanced routing result with Agent Booster support
 */
export interface EnhancedRouteResult {
  tier: 1 | 2 | 3;
  handler: 'codemod' | 'agent-booster' | 'haiku' | 'sonnet' | 'opus';
  model?: ClaudeModel;
  confidence: number;
  complexity?: number;
  reasoning: string;
  /** The detected edit intent (Tier 1 only). */
  codemodIntent?: EditIntent;
  /**
   * Back-compat alias for {@link codemodIntent}. Older callers read this field.
   * @deprecated use {@link codemodIntent}
   */
  agentBoosterIntent?: EditIntent;
  /** true when a deterministic, $0 codemod can fully apply this edit (no LLM). */
  deterministic?: boolean;
  canSkipLLM?: boolean;
  estimatedLatencyMs: number;
  estimatedCost: number;
}

/**
 * Enhanced model router configuration
 */
export interface EnhancedModelRouterConfig {
  agentBoosterEnabled: boolean;
  agentBoosterConfidenceThreshold: number;
  enabledIntents: EditIntentType[];
  complexityThresholds: {
    haiku: number;
    sonnet: number;
    opus: number;
  };
  preferCost: boolean;
  preferQuality: boolean;
}

// ============================================================================
// Intent Detection Patterns
// ============================================================================

/**
 * Pattern definitions for Agent Booster intent detection
 */
const INTENT_PATTERNS: Record<EditIntentType, {
  patterns: RegExp[];
  weight: number;
  description: string;
}> = {
  'var-to-const': {
    patterns: [
      /convert\s+var\s+to\s+const/i,
      /change\s+var\s+to\s+const/i,
      /change\s+var\s+declarations?\s+to\s+const/i,
      /replace\s+var\s+with\s+const/i,
      /var\s*(?:→|->|to)\s*const/i,
      /use\s+const\s+instead\s+of\s+var/i,
    ],
    weight: 1.0,
    description: 'Convert var declarations to const/let',
  },
  'add-types': {
    patterns: [
      /add\s+type\s+annotations?/i,
      /add\s+typescript\s+types?/i,
      /type\s+this\s+function/i,
      /add\s+types?\s+to/i,
      /annotate\s+with\s+types?/i,
    ],
    weight: 0.9,
    description: 'Add TypeScript type annotations',
  },
  'add-error-handling': {
    patterns: [
      /add\s+error\s+handling/i,
      /wrap\s+in\s+try\s*[/-]?\s*catch/i,
      /add\s+try\s*[/-]?\s*catch/i,
      /handle\s+errors?/i,
      /add\s+exception\s+handling/i,
    ],
    weight: 0.7, // Lower weight - often needs more context
    description: 'Wrap code in try/catch blocks',
  },
  'async-await': {
    patterns: [
      /convert\s+to\s+async\s*[/-]?\s*await/i,
      /convert\s+\w+\s+to\s+async/i,
      /use\s+async\s*[/-]?\s*await/i,
      /change\s+promises?\s+to\s+async/i,
      /refactor\s+to\s+async/i,
      /\.then\s*(?:→|->|to)\s*await/i,
      /callback\s+to\s+async/i,
      /callbacks?\s+to\s+async/i,
    ],
    weight: 0.8,
    description: 'Convert callbacks/promises to async/await',
  },
  'add-logging': {
    patterns: [
      /add\s+logging/i,
      /add\s+console\.log/i,
      /add\s+debug\s+logs?/i,
      /log\s+this\s+function/i,
      /add\s+trace\s+logging/i,
    ],
    weight: 0.85,
    description: 'Add console.log or logging statements',
  },
  'remove-console': {
    patterns: [
      /remove\s+(?:all\s+)?console\.log/i,
      /remove\s+(?:all\s+)?console\s+statements?/i,
      /delete\s+(?:all\s+)?console\s+statements?/i,
      /strip\s+console/i,
      /clean\s+up\s+console/i,
      /clean\s+up\s+debug\s+logs?/i,
      /remove\s+(?:all\s+)?debug\s+logs?/i,
      /delete\s+(?:all\s+)?console\.log/i,
    ],
    weight: 0.95,
    description: 'Remove console.* calls',
  },
};

/**
 * File path extraction patterns
 */
const FILE_PATH_PATTERNS: RegExp[] = [
  /(?:in|from|to|file|path)\s+[`"']?([a-zA-Z0-9_./\\-]+\.[a-zA-Z]+)[`"']?/i,
  /[`"']([a-zA-Z0-9_./\\-]+\.[a-zA-Z]+)[`"']/,
  /(\S+\.[tj]sx?)\b/i,
  /(\S+\.(?:js|ts|jsx|tsx|py|rb|go|rs|java|kt|swift|c|cpp|h))\b/i,
];

/**
 * Language detection by extension
 */
/**
 * High-complexity keywords that indicate Tier 3 (Opus) routing
 * These tasks require deep reasoning and architectural understanding
 */
const TIER3_KEYWORDS: RegExp[] = [
  // Architecture & Design
  /\b(microservices?|architecture|system\s+design|distributed)\b/i,
  /\b(design|architect|plan)\s+(a|an|the|complex)\b/i,
  /\b(design)\s+\w+\s+(schema|system|architecture)\b/i,

  // Security
  /\b(oauth2?|pkce|jwt|rbac|authentication\s+system|security\s+audit)\b/i,
  /\b(refresh\s+token|token\s+rotation|role-based|permission|authorization)\b/i,
  /\b(encryption|cryptograph|certificate|ssl|tls)\b/i,
  /\b(end-to-end\s+encryption|key\s+rotation|secure\s+channel)\b/i,

  // Distributed Systems
  /\b(consensus|distributed|byzantine|raft|paxos)\b/i,
  /\b(replication|sharding|partitioning|eventual\s+consistency)\b/i,
  /\b(load\s+balanc|fault[- ]toleran|high\s+availability)\b/i,
  /\b(message\s+queue|event\s+sourc|cqrs|saga)\b/i,

  // Complex Algorithms
  /\b(algorithm|machine\s+learning|neural|optimization)\b/i,
  /\b(graph\s+algorithm|tree\s+traversal|dynamic\s+programming)\b/i,

  // Database Design
  /\b(schema\s+design|database\s+architect|data\s+model)\b/i,
  /\b(database\s+schema|multi[- ]tenant)\b/i,
  /\b(normalization|denormalization|index\s+strateg)\b/i,

  // Performance Critical
  /\b(performance\s+critical|low\s+latency|high\s+throughput)\b/i,
  /\b(memory\s+optimi|cache\s+strateg|concurrent)\b/i,
];

const LANGUAGE_MAP: Record<string, string> = {
  '.js': 'javascript',
  '.jsx': 'javascript',
  '.ts': 'typescript',
  '.tsx': 'typescript',
  '.py': 'python',
  '.rb': 'ruby',
  '.go': 'go',
  '.rs': 'rust',
  '.java': 'java',
  '.kt': 'kotlin',
  '.swift': 'swift',
  '.c': 'c',
  '.cpp': 'cpp',
  '.h': 'c',
};

// ============================================================================
// Enhanced Model Router Implementation
// ============================================================================

/**
 * Enhanced Model Router with Agent Booster AST integration
 *
 * Provides intelligent 3-tier routing:
 * - Tier 1: Agent Booster for simple code transforms (352x faster, $0)
 * - Tier 2: Haiku for low complexity tasks
 * - Tier 3: Sonnet/Opus for complex reasoning tasks
 */
export class EnhancedModelRouter {
  private config: EnhancedModelRouterConfig;
  // The base text-routing path delegated to here is the local
  // heuristic + Thompson-bandit ModelRouter — NOT the @ruvector/tiny-dancer
  // neural router that an earlier design (ADR-026) described (#2329). The
  // public `getStats()` return still exposes the field as `tinyDancerStats`
  // for telemetry-schema stability.
  private baseRouter: ModelRouter;

  constructor(config?: Partial<EnhancedModelRouterConfig>) {
    this.config = {
      agentBoosterEnabled: true,
      agentBoosterConfidenceThreshold: 0.7,
      enabledIntents: [
        'var-to-const',
        'add-types',
        'add-error-handling',
        'async-await',
        'add-logging',
        'remove-console',
      ],
      complexityThresholds: {
        haiku: 0.3,
        sonnet: 0.6,
        opus: 1.0,
      },
      preferCost: false,
      preferQuality: false,
      ...config,
    };

    this.baseRouter = getModelRouter();
  }

  /**
   * Detect code editing intent from task description
   */
  detectIntent(task: string): EditIntent | null {
    const taskLower = task.toLowerCase();
    let bestIntent: EditIntent | null = null;
    let bestScore = 0;

    for (const [intentType, config] of Object.entries(INTENT_PATTERNS)) {
      if (!this.config.enabledIntents.includes(intentType as EditIntentType)) {
        continue;
      }

      for (const pattern of config.patterns) {
        if (pattern.test(taskLower)) {
          const score = config.weight;
          if (score > bestScore) {
            bestScore = score;
            bestIntent = {
              type: intentType as EditIntentType,
              confidence: score,
              description: config.description,
            };
          }
        }
      }
    }

    // Extract file path if intent found
    if (bestIntent) {
      const filePath = this.extractFilePath(task);
      if (filePath) {
        bestIntent.filePath = filePath;
        bestIntent.language = this.detectLanguage(filePath);
        // Boost confidence if file exists
        if (existsSync(filePath)) {
          bestIntent.confidence = Math.min(1.0, bestIntent.confidence + 0.1);
        }
      }
    }

    return bestIntent;
  }

  /**
   * Extract file path from task description
   */
  private extractFilePath(task: string): string | null {
    for (const pattern of FILE_PATH_PATTERNS) {
      const match = task.match(pattern);
      if (match && match[1]) {
        return match[1];
      }
    }
    return null;
  }

  /**
   * Detect language from file extension
   */
  private detectLanguage(filePath: string): string {
    const ext = extname(filePath).toLowerCase();
    return LANGUAGE_MAP[ext] || 'javascript';
  }

  /**
   * Check if task contains Tier 3 (Opus) keywords
   */
  private containsTier3Keywords(task: string): { matches: boolean; count: number } {
    let count = 0;
    for (const pattern of TIER3_KEYWORDS) {
      if (pattern.test(task)) {
        count++;
      }
    }
    return { matches: count > 0, count };
  }

  /**
   * Route a task to the optimal tier and handler
   */
  async route(task: string, context?: { filePath?: string }): Promise<EnhancedRouteResult> {
    // Step 1: Deterministic codemod detection (ADR-143).
    // Only intents that a codemod can apply *deterministically and safely* skip
    // the LLM. Intents that need inference (add-types, add-error-handling,
    // async-await) are detected but fall through to model routing below.
    if (this.config.agentBoosterEnabled) {
      const intent = this.detectIntent(task);

      if (
        intent &&
        intent.confidence >= this.config.agentBoosterConfidenceThreshold &&
        isDeterministicCodemod(intent.type)
      ) {
        // Route-time dry-run (ADR-143 #3): when a target file is known, only
        // claim Tier-1 if the codemod actually changes something. This avoids
        // recommending [CODEMOD_AVAILABLE] for no-ops (e.g. "remove console" on
        // a file with no console calls). With no file to check, recommend Tier-1
        // best-effort — the executor (hooks_codemod) verifies before writing.
        // Prefer the caller-provided path (authoritative, usually absolute) over
        // the path heuristically extracted from the task text; resolve relatives.
        const fpRaw = context?.filePath || intent.filePath;
        const fp = fpRaw ? (isAbsolute(fpRaw) ? fpRaw : resolvePath(process.cwd(), fpRaw)) : undefined;
        let tier1 = true;
        let edits: number | undefined;
        if (fp && existsSync(fp)) {
          try {
            const code = readFileSync(fp, 'utf-8');
            const res = applyCodemod(intent.type, code, { language: codemodLanguageFor(fp, intent.language) });
            if (res.success && res.changed) {
              edits = res.edits;
            } else {
              tier1 = false; // verified no-op / can't apply → fall through to model routing
            }
          } catch {
            // read error → leave best-effort Tier-1 (executor will verify)
          }
        }

        if (tier1) {
          const editsNote = edits !== undefined ? ` (${edits} edit${edits === 1 ? '' : 's'})` : '';
          return {
            tier: 1,
            handler: 'codemod',
            confidence: intent.confidence,
            reasoning: `Deterministic codemod can apply "${intent.type}" with ${(intent.confidence * 100).toFixed(0)}% confidence — $0, no LLM${editsNote}`,
            codemodIntent: intent,
            agentBoosterIntent: intent,
            deterministic: true,
            canSkipLLM: true,
            estimatedLatencyMs: 1,
            estimatedCost: 0,
          };
        }
        // verified no-op: fall through to model routing below
      }
    }

    // Step 2: Check for Tier 3 keywords (architecture, security, distributed)
    const tier3Check = this.containsTier3Keywords(task);
    if (tier3Check.matches && tier3Check.count >= 2) {
      // Strong signal for Opus - multiple complex keywords
      return {
        tier: 3,
        handler: 'opus',
        model: 'opus',
        confidence: Math.min(0.95, 0.7 + tier3Check.count * 0.1),
        complexity: 0.8 + tier3Check.count * 0.05,
        reasoning: `High complexity task (${tier3Check.count} architectural keywords) - using opus`,
        canSkipLLM: false,
        estimatedLatencyMs: 5000,
        estimatedCost: 0.015,
      };
    }

    // Step 3: AST complexity analysis (if file path provided)
    let astComplexity: number | undefined;
    const targetFile = context?.filePath || this.extractFilePath(task);

    if (targetFile && existsSync(targetFile)) {
      try {
        astComplexity = await this.analyzeASTComplexity(targetFile);
      } catch {
        // AST analysis not available, continue with text-based routing
      }
    }

    // Step 4: Text-based complexity via the local heuristic + bandit router.
    const baseResult = await this.baseRouter.route(task);

    // Step 5: Combine AST complexity with the text-routing result.
    // Also boost if a single tier3 keyword is found.
    let finalComplexity = astComplexity !== undefined
      ? (astComplexity + baseResult.complexity) / 2
      : baseResult.complexity;

    // Boost complexity if tier3 keywords found (even just one)
    if (tier3Check.matches) {
      finalComplexity = Math.min(1.0, finalComplexity + 0.25);
    }

    // Step 6: Determine tier based on complexity
    const { haiku, sonnet } = this.config.complexityThresholds;

    if (finalComplexity < haiku) {
      return {
        tier: 2,
        handler: 'haiku',
        model: 'haiku',
        confidence: baseResult.confidence,
        complexity: finalComplexity,
        reasoning: `Low complexity (${(finalComplexity * 100).toFixed(0)}%) - using haiku`,
        canSkipLLM: false,
        estimatedLatencyMs: 500,
        estimatedCost: 0.0002,
      };
    }

    if (finalComplexity < sonnet) {
      return {
        tier: 2,
        handler: 'sonnet',
        model: 'sonnet',
        confidence: baseResult.confidence,
        complexity: finalComplexity,
        reasoning: `Medium complexity (${(finalComplexity * 100).toFixed(0)}%) - using sonnet`,
        canSkipLLM: false,
        estimatedLatencyMs: 2000,
        estimatedCost: 0.003,
      };
    }

    return {
      tier: 3,
      handler: 'opus',
      model: 'opus',
      confidence: baseResult.confidence,
      complexity: finalComplexity,
      reasoning: `High complexity (${(finalComplexity * 100).toFixed(0)}%) - using opus`,
      canSkipLLM: false,
      estimatedLatencyMs: 5000,
      estimatedCost: 0.015,
    };
  }

  /**
   * Analyze AST complexity of a file
   * Returns normalized complexity score (0-1)
   */
  private async analyzeASTComplexity(filePath: string): Promise<number> {
    try {
      const content = readFileSync(filePath, 'utf-8');
      const lines = content.split('\n');

      // Simple heuristics for complexity
      let complexity = 0;

      // Line count contribution
      complexity += Math.min(0.3, lines.length / 1000);

      // Nesting depth estimation (count indentation)
      const avgIndent = lines
        .filter((l) => l.trim().length > 0)
        .map((l) => l.match(/^(\s*)/)?.[1].length || 0)
        .reduce((sum, indent) => sum + indent, 0) / Math.max(1, lines.length);
      complexity += Math.min(0.2, avgIndent / 20);

      // Control flow complexity (count keywords)
      const controlFlowCount = (content.match(/\b(if|else|for|while|switch|case|try|catch|async|await)\b/g) || []).length;
      complexity += Math.min(0.3, controlFlowCount / 100);

      // Function/class count
      const functionCount = (content.match(/\b(function|class|=>)\b/g) || []).length;
      complexity += Math.min(0.2, functionCount / 50);

      return Math.min(1, complexity);
    } catch {
      return 0.5; // Default to medium complexity on error
    }
  }

  /**
   * Execute task using the appropriate tier.
   *
   * For Tier-1 deterministic intents this applies the codemod directly (writing
   * the file back when a path is given) — $0, no LLM. Otherwise it returns the
   * routing result and the caller invokes the recommended model.
   */
  async execute(
    task: string,
    context?: { filePath?: string; originalCode?: string }
  ): Promise<{
    result: string | { applied: boolean; changed: boolean; edits: number };
    routeResult: EnhancedRouteResult;
  }> {
    const routeResult = await this.route(task, context);
    const intent = routeResult.codemodIntent ?? routeResult.agentBoosterIntent;

    if (routeResult.tier === 1 && routeResult.deterministic && intent) {
      const cm = this.tryCodemod(intent, context);

      if (cm.success) {
        return {
          result: { applied: true, changed: cm.changed, edits: cm.edits },
          routeResult,
        };
      }

      // Codemod could not apply (no file / parse issue) — fall back to a model.
      routeResult.tier = 2;
      routeResult.handler = 'sonnet';
      routeResult.model = 'sonnet';
      routeResult.deterministic = false;
      routeResult.canSkipLLM = false;
      routeResult.reasoning += ' (codemod fallback to LLM)';
    }

    // Return routing result - caller handles LLM invocation
    return { result: routeResult.reasoning, routeResult };
  }

  /**
   * Apply a deterministic codemod to the intent's target file.
   *
   * This is the real Tier-1 execution path (ADR-143). It uses the in-process
   * TypeScript-compiler codemod engine — no `agent-booster` import, no subprocess,
   * no LLM. Writes the transformed source back to disk when it changes.
   */
  private tryCodemod(
    intent: EditIntent,
    context?: { filePath?: string; originalCode?: string }
  ): { success: boolean; changed: boolean; edits: number } {
    const filePath = intent.filePath || context?.filePath;
    if (!filePath || !existsSync(filePath)) {
      return { success: false, changed: false, edits: 0 };
    }

    const originalCode = context?.originalCode ?? readFileSync(filePath, 'utf-8');
    const language = codemodLanguageFor(filePath, intent.language);
    const result = applyCodemod(intent.type, originalCode, { language });

    if (!result.success) {
      return { success: false, changed: false, edits: 0 };
    }
    if (result.changed && !context?.originalCode) {
      writeFileSync(filePath, result.output, 'utf-8');
    }
    return { success: true, changed: result.changed, edits: result.edits };
  }

  /**
   * Get router statistics
   */
  getStats(): {
    config: EnhancedModelRouterConfig;
    tinyDancerStats: ReturnType<ModelRouter['getStats']>;
  } {
    return {
      config: { ...this.config },
      // Field name kept as `tinyDancerStats` for telemetry-schema
      // stability; the underlying router is the local heuristic + bandit
      // ModelRouter, not @ruvector/tiny-dancer. See #2329.
      tinyDancerStats: this.baseRouter.getStats(),
    };
  }
}

