/**
 * Q-Learning Router for Task Routing
 *
 * Uses reinforcement learning to optimize task routing decisions
 * based on historical performance and context.
 *
 * Features:
 * - Caching for repeated task patterns (LRU cache)
 * - Optimized state space with feature hashing
 * - Epsilon decay with exponential annealing
 * - Experience replay buffer for stable learning
 * - Model persistence to .swarm/q-learning-model.json
 *
 * @module q-learning-router
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname, join } from 'path';

/**
 * Q-Learning Router Configuration
 */
export interface QLearningRouterConfig {
  /** Learning rate (default: 0.1) */
  learningRate: number;
  /** Discount factor (default: 0.99) */
  gamma: number;
  /** Initial exploration rate (default: 1.0) */
  explorationInitial: number;
  /** Final exploration rate (default: 0.01) */
  explorationFinal: number;
  /** Exploration decay steps (default: 10000) */
  explorationDecay: number;
  /** Exploration decay type (default: 'exponential') */
  explorationDecayType: 'linear' | 'exponential' | 'cosine';
  /** Maximum states in Q-table (default: 10000) */
  maxStates: number;
  /** Number of actions/routes (default: 8) */
  numActions: number;
  /** Experience replay buffer size (default: 1000) */
  replayBufferSize: number;
  /** Mini-batch size for replay (default: 32) */
  replayBatchSize: number;
  /** Enable experience replay (default: true) */
  enableReplay: boolean;
  /** Route cache size (default: 256) */
  cacheSize: number;
  /** Cache TTL in milliseconds (default: 300000 = 5 minutes) */
  cacheTTL: number;
  /** Model persistence path (default: '.swarm/q-learning-model.json') */
  modelPath: string;
  /** Auto-save interval in updates (default: 100) */
  autoSaveInterval: number;
  /** State space dimensionality for feature hashing (default: 64) */
  stateSpaceDim: number;
}

/**
 * Route decision result
 */
export interface RouteDecision {
  /** Selected route/action */
  route: string;
  /** Confidence score (0-1) */
  confidence: number;
  /** Q-values for all routes */
  qValues: number[];
  /** Was exploration used */
  explored: boolean;
  /** Route alternatives */
  alternatives: Array<{ route: string; score: number }>;
}

/**
 * Q-table entry
 */
interface QEntry {
  qValues: Float32Array;
  visits: number;
  lastUpdate: number;
  /** Eligibility trace for TD(lambda) */
  eligibility?: Float32Array;
}

/**
 * Experience tuple for replay buffer
 */
interface Experience {
  stateKey: string;
  actionIdx: number;
  reward: number;
  nextStateKey: string | null;
  timestamp: number;
  priority: number;
}

/**
 * Cache entry for route decisions
 */
interface CacheEntry {
  decision: RouteDecision;
  timestamp: number;
  hits: number;
}

/**
 * Persisted model structure
 */
interface PersistedModel {
  version: string;
  /**
   * State-key encoder version. v1 was the 31-bit truncating fold that
   * silently discarded the keyword block (features 0–31). v2 is a lossless
   * 32-bit FNV-1a fold over the full quantized vector. See #2239.
   *
   * On version mismatch, the qTable is reset (keys are computed with the old
   * encoder and would never be matched by new lookups); stats/epsilon are kept.
   */
  encoderVersion?: number;
  config: Partial<QLearningRouterConfig>;
  qTable: Record<string, { qValues: number[]; visits: number }>;
  stats: {
    stepCount: number;
    updateCount: number;
    avgTDError: number;
    epsilon: number;
  };
  metadata: {
    savedAt: string;
    totalExperiences: number;
  };
}

/** Current state-key encoder version (see PersistedModel.encoderVersion). */
const ENCODER_VERSION = 2;

/**
 * Default configuration
 */
const DEFAULT_CONFIG: QLearningRouterConfig = {
  learningRate: 0.1,
  gamma: 0.99,
  explorationInitial: 1.0,
  explorationFinal: 0.01,
  explorationDecay: 10000,
  explorationDecayType: 'exponential',
  maxStates: 10000,
  numActions: 8,
  replayBufferSize: 1000,
  replayBatchSize: 32,
  enableReplay: true,
  cacheSize: 256,
  cacheTTL: 300000,
  modelPath: '.swarm/q-learning-model.json',
  autoSaveInterval: 100,
  stateSpaceDim: 64,
};

/**
 * Route names mapping
 */
const ROUTE_NAMES = [
  'coder',
  'tester',
  'reviewer',
  'architect',
  'researcher',
  'optimizer',
  'debugger',
  'documenter',
];

/**
 * Task feature keywords for state representation
 */
const FEATURE_KEYWORDS = [
  // Code-related
  'implement', 'code', 'write', 'create', 'build', 'develop',
  // Testing-related
  'test', 'spec', 'coverage', 'unit', 'integration', 'e2e',
  // Review-related
  'review', 'check', 'audit', 'analyze', 'inspect',
  // Architecture-related
  'architect', 'design', 'structure', 'pattern', 'system',
  // Research-related
  'research', 'investigate', 'explore', 'find', 'search',
  // Optimization-related
  'optimize', 'performance', 'speed', 'memory', 'improve',
  // Debug-related
  'debug', 'fix', 'bug', 'error', 'issue', 'problem',
  // Documentation-related
  'document', 'docs', 'readme', 'comment', 'explain',
];

/**
 * Q-Learning Router for intelligent task routing
 *
 * Optimized with:
 * - LRU cache for repeated task patterns
 * - Feature hashing for efficient state space
 * - Exponential epsilon decay
 * - Prioritized experience replay
 * - Model persistence
 */
export class QLearningRouter {
  private config: QLearningRouterConfig;
  private qTable: Map<string, QEntry> = new Map();
  private epsilon: number;
  private stepCount = 0;
  private updateCount = 0;
  private avgTDError = 0;
  private ruvectorEngine: unknown = null;
  private useNative = false;

  // Experience replay buffer (circular buffer)
  private replayBuffer: Experience[] = [];
  private replayBufferIdx = 0;
  private totalExperiences = 0;

  // LRU cache for route decisions
  private routeCache: Map<string, CacheEntry> = new Map();
  private cacheOrder: string[] = [];
  private cacheHits = 0;
  private cacheMisses = 0;

  // Feature hash cache for state representation
  private featureHashCache: Map<string, Float32Array> = new Map();

  constructor(config: Partial<QLearningRouterConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.epsilon = this.config.explorationInitial;
  }

  /**
   * Initialize the router, attempting to load ruvector native module
   * and restore persisted model if available
   */
  async initialize(): Promise<void> {
    try {
      const ruvector = await import('@ruvector/core');
      this.ruvectorEngine = (ruvector as any).createQLearning?.(this.config);
      this.useNative = !!this.ruvectorEngine;
    } catch {
      // Fallback to JS implementation
      this.useNative = false;
    }

    // Try to load persisted model
    await this.loadModel();
  }

  /**
   * Load model from persistence file
   */
  async loadModel(path?: string): Promise<boolean> {
    const modelPath = path || this.config.modelPath;
    try {
      if (!existsSync(modelPath)) {
        return false;
      }
      const data = readFileSync(modelPath, 'utf-8');
      const model: PersistedModel = JSON.parse(data);

      // Validate version compatibility
      if (!model.version || !model.version.startsWith('1.')) {
        console.warn(`[Q-Learning] Incompatible model version: ${model.version}`);
        return false;
      }

      // #2239 — Encoder-version migration guard. v1 state keys were computed
      // by a fold that silently dropped the keyword block, so they cannot be
      // matched by v2 lookups. Skip the qTable import on mismatch (keep
      // stats/epsilon so learning curve survives a restart).
      const persistedEncoder = model.encoderVersion ?? 1;
      if (persistedEncoder === ENCODER_VERSION) {
        this.import(model.qTable);
      } else {
        console.warn(
          `[Q-Learning] Encoder version mismatch (persisted=${persistedEncoder}, current=${ENCODER_VERSION}); resetting Q-table (see #2239).`,
        );
      }

      // Restore stats
      this.stepCount = model.stats.stepCount || 0;
      this.updateCount = model.stats.updateCount || 0;
      this.avgTDError = model.stats.avgTDError || 0;
      this.epsilon = model.stats.epsilon || this.config.explorationInitial;
      this.totalExperiences = model.metadata?.totalExperiences || 0;

      return true;
    } catch (err) {
      console.warn(`[Q-Learning] Failed to load model: ${err}`);
      return false;
    }
  }

  /**
   * Save model to persistence file
   */
  async saveModel(path?: string): Promise<boolean> {
    const modelPath = path || this.config.modelPath;
    try {
      // Ensure directory exists
      const dir = dirname(modelPath);
      if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }

      const model: PersistedModel = {
        version: '1.0.0',
        encoderVersion: ENCODER_VERSION, // #2239
        config: {
          learningRate: this.config.learningRate,
          gamma: this.config.gamma,
          explorationDecayType: this.config.explorationDecayType,
          numActions: this.config.numActions,
        },
        qTable: this.export(),
        stats: {
          stepCount: this.stepCount,
          updateCount: this.updateCount,
          avgTDError: this.avgTDError,
          epsilon: this.epsilon,
        },
        metadata: {
          savedAt: new Date().toISOString(),
          totalExperiences: this.totalExperiences,
        },
      };

      writeFileSync(modelPath, JSON.stringify(model, null, 2));
      return true;
    } catch (err) {
      console.warn(`[Q-Learning] Failed to save model: ${err}`);
      return false;
    }
  }

  /**
   * Route a task based on its context
   * Uses LRU cache for repeated task patterns
   */
  route(taskContext: string, explore: boolean = true): RouteDecision {
    const stateKey = this.hashStateOptimized(taskContext);

    // Check cache first (only for exploitation, not exploration)
    if (!explore) {
      const cached = this.getCachedRoute(stateKey);
      if (cached) {
        this.cacheHits++;
        return cached;
      }
      this.cacheMisses++;
    }

    // Check if we should explore using decayed epsilon
    const shouldExplore = explore && Math.random() < this.epsilon;

    let actionIdx: number;
    let qValues: number[];

    if (shouldExplore) {
      // Random exploration
      actionIdx = Math.floor(Math.random() * this.config.numActions);
      qValues = this.getQValues(stateKey);
    } else {
      // Exploit - choose best action
      qValues = this.getQValues(stateKey);
      actionIdx = this.argmax(qValues);
    }

    // Calculate confidence from softmax of Q-values
    const confidence = this.softmaxConfidence(qValues, actionIdx);

    // Get alternatives sorted by Q-value
    const alternatives = ROUTE_NAMES
      .map((route, idx) => ({ route, score: qValues[idx] }))
      .sort((a, b) => b.score - a.score)
      .slice(1, 4); // Top 3 alternatives

    const decision: RouteDecision = {
      route: ROUTE_NAMES[actionIdx] || 'coder',
      confidence,
      qValues,
      explored: shouldExplore,
      alternatives,
    };

    // Cache the decision for exploitation queries
    if (!shouldExplore) {
      this.cacheRoute(stateKey, decision);
    }

    return decision;
  }

  /**
   * Get cached route decision (LRU cache)
   */
  private getCachedRoute(stateKey: string): RouteDecision | null {
    const entry = this.routeCache.get(stateKey);
    if (!entry) {
      return null;
    }

    // Check TTL
    if (Date.now() - entry.timestamp > this.config.cacheTTL) {
      this.routeCache.delete(stateKey);
      this.cacheOrder = this.cacheOrder.filter(k => k !== stateKey);
      return null;
    }

    // Update LRU order
    this.cacheOrder = this.cacheOrder.filter(k => k !== stateKey);
    this.cacheOrder.push(stateKey);
    entry.hits++;

    return entry.decision;
  }

  /**
   * Cache a route decision (LRU eviction)
   */
  private cacheRoute(stateKey: string, decision: RouteDecision): void {
    // Evict oldest if cache is full
    while (this.routeCache.size >= this.config.cacheSize && this.cacheOrder.length > 0) {
      const oldest = this.cacheOrder.shift();
      if (oldest) {
        this.routeCache.delete(oldest);
      }
    }

    this.routeCache.set(stateKey, {
      decision,
      timestamp: Date.now(),
      hits: 0,
    });
    this.cacheOrder.push(stateKey);
  }

  /**
   * Invalidate cache (call after significant Q-table updates)
   */
  invalidateCache(): void {
    this.routeCache.clear();
    this.cacheOrder = [];
  }

  /** Invalidate a single state's cached route (called after its Q-values change
   * so the next route() reflects the update immediately). */
  private invalidateCacheEntry(stateKey: string): void {
    if (this.routeCache.delete(stateKey)) {
      this.cacheOrder = this.cacheOrder.filter(k => k !== stateKey);
    }
  }

  /**
   * Update Q-values based on feedback
   * Includes experience replay for stable learning
   */
  update(taskContext: string, action: string, reward: number, nextContext?: string): number {
    const stateKey = this.hashStateOptimized(taskContext);
    const actionIdx = ROUTE_NAMES.indexOf(action);

    if (actionIdx === -1) {
      return 0;
    }

    const nextStateKey = nextContext ? this.hashStateOptimized(nextContext) : null;

    // Store experience in replay buffer
    if (this.config.enableReplay) {
      const experience: Experience = {
        stateKey,
        actionIdx,
        reward,
        nextStateKey,
        timestamp: Date.now(),
        priority: Math.abs(reward) + 0.1, // Initial priority based on reward magnitude
      };
      this.addToReplayBuffer(experience);
    }

    // Perform direct update
    const tdError = this.updateQValue(stateKey, actionIdx, reward, nextStateKey);

    // #cache-staleness: invalidate THIS state's cached route immediately. The
    // periodic full invalidation (every 50 updates) otherwise left a freshly
    // learned Q-update hidden behind a stale cached decision, so feedback
    // appeared to have no effect on routing until 50 updates accumulated.
    this.invalidateCacheEntry(stateKey);

    // Perform experience replay
    if (this.config.enableReplay && this.replayBuffer.length >= this.config.replayBatchSize) {
      this.experienceReplay();
    }

    // Decay exploration using configured strategy
    this.stepCount++;
    this.epsilon = this.calculateEpsilon();

    // Prune Q-table if needed
    if (this.qTable.size > this.config.maxStates) {
      this.pruneQTable();
    }

    this.updateCount++;
    this.avgTDError = (this.avgTDError * (this.updateCount - 1) + Math.abs(tdError)) / this.updateCount;

    // Auto-save periodically
    if (this.config.autoSaveInterval > 0 && this.updateCount % this.config.autoSaveInterval === 0) {
      this.saveModel().catch(() => {}); // Fire and forget
    }

    // Invalidate cache periodically to reflect Q-table changes
    if (this.updateCount % 50 === 0) {
      this.invalidateCache();
    }

    return tdError;
  }

  /**
   * Internal Q-value update
   */
  private updateQValue(stateKey: string, actionIdx: number, reward: number, nextStateKey: string | null): number {
    const entry = this.getOrCreateEntry(stateKey);
    const currentQ = entry.qValues[actionIdx];

    // Calculate target Q-value
    let targetQ: number;
    if (nextStateKey) {
      const nextQValues = this.getQValues(nextStateKey);
      const maxNextQ = Math.max(...nextQValues);
      targetQ = reward + this.config.gamma * maxNextQ;
    } else {
      // Terminal state
      targetQ = reward;
    }

    // TD error
    const tdError = targetQ - currentQ;

    // Update Q-value
    entry.qValues[actionIdx] += this.config.learningRate * tdError;
    entry.visits++;
    entry.lastUpdate = Date.now();

    return tdError;
  }

  /**
   * Add experience to circular replay buffer
   */
  private addToReplayBuffer(experience: Experience): void {
    if (this.replayBuffer.length < this.config.replayBufferSize) {
      this.replayBuffer.push(experience);
    } else {
      this.replayBuffer[this.replayBufferIdx] = experience;
    }
    this.replayBufferIdx = (this.replayBufferIdx + 1) % this.config.replayBufferSize;
    this.totalExperiences++;
  }

  /**
   * Perform prioritized experience replay
   * Samples mini-batch from buffer and updates Q-values
   */
  private experienceReplay(): void {
    if (this.replayBuffer.length < this.config.replayBatchSize) {
      return;
    }

    // Prioritized sampling based on TD error magnitude
    const batch = this.samplePrioritizedBatch(this.config.replayBatchSize);

    for (const exp of batch) {
      const tdError = this.updateQValue(exp.stateKey, exp.actionIdx, exp.reward, exp.nextStateKey);

      // Update priority for future sampling
      exp.priority = Math.abs(tdError) + 0.01; // Small constant to avoid zero priority
    }
  }

  /**
   * Sample a prioritized batch from replay buffer
   * Uses proportional prioritization
   */
  private samplePrioritizedBatch(batchSize: number): Experience[] {
    const totalPriority = this.replayBuffer.reduce((sum, exp) => sum + exp.priority, 0);
    const batch: Experience[] = [];
    const selected = new Set<number>();

    while (batch.length < batchSize && selected.size < this.replayBuffer.length) {
      let threshold = Math.random() * totalPriority;
      let cumSum = 0;

      for (let i = 0; i < this.replayBuffer.length; i++) {
        if (selected.has(i)) continue;

        cumSum += this.replayBuffer[i].priority;
        if (cumSum >= threshold) {
          batch.push(this.replayBuffer[i]);
          selected.add(i);
          break;
        }
      }
    }

    return batch;
  }

  /**
   * Calculate epsilon using configured decay strategy
   */
  private calculateEpsilon(): number {
    const { explorationInitial, explorationFinal, explorationDecay, explorationDecayType } = this.config;
    const progress = Math.min(this.stepCount / explorationDecay, 1.0);

    switch (explorationDecayType) {
      case 'linear':
        return explorationFinal + (explorationInitial - explorationFinal) * (1 - progress);

      case 'exponential':
        // Exponential decay: epsilon = final + (initial - final) * exp(-decay_rate * step)
        const decayRate = -Math.log((explorationFinal / explorationInitial) + 1e-8) / explorationDecay;
        return explorationFinal + (explorationInitial - explorationFinal) * Math.exp(-decayRate * this.stepCount);

      case 'cosine':
        // Cosine annealing: smooth transition
        return explorationFinal + (explorationInitial - explorationFinal) * 0.5 * (1 + Math.cos(Math.PI * progress));

      default:
        return Math.max(explorationFinal, explorationInitial - this.stepCount / explorationDecay);
    }
  }

  /**
   * Get statistics including cache and replay buffer metrics
   */
  getStats(): Record<string, number> {
    const cacheHitRate = this.cacheHits + this.cacheMisses > 0
      ? this.cacheHits / (this.cacheHits + this.cacheMisses)
      : 0;

    return {
      updateCount: this.updateCount,
      qTableSize: this.qTable.size,
      epsilon: this.epsilon,
      avgTDError: this.avgTDError,
      stepCount: this.stepCount,
      useNative: this.useNative ? 1 : 0,
      // Cache metrics
      cacheSize: this.routeCache.size,
      cacheHits: this.cacheHits,
      cacheMisses: this.cacheMisses,
      cacheHitRate,
      // Replay buffer metrics
      replayBufferSize: this.replayBuffer.length,
      totalExperiences: this.totalExperiences,
      // Feature hash cache
      featureHashCacheSize: this.featureHashCache.size,
    };
  }

  /**
   * Reset the router (clears all learned data)
   */
  reset(): void {
    this.qTable.clear();
    this.epsilon = this.config.explorationInitial;
    this.stepCount = 0;
    this.updateCount = 0;
    this.avgTDError = 0;

    // Reset replay buffer
    this.replayBuffer = [];
    this.replayBufferIdx = 0;
    this.totalExperiences = 0;

    // Reset cache
    this.routeCache.clear();
    this.cacheOrder = [];
    this.cacheHits = 0;
    this.cacheMisses = 0;

    // Reset feature hash cache
    this.featureHashCache.clear();
  }

  /**
   * Export Q-table for persistence
   */
  export(): Record<string, { qValues: number[]; visits: number }> {
    const result: Record<string, { qValues: number[]; visits: number }> = {};
    for (const [key, entry] of this.qTable) {
      result[key] = {
        qValues: Array.from(entry.qValues),
        visits: entry.visits,
      };
    }
    return result;
  }

  /**
   * Import Q-table from persistence
   */
  import(data: Record<string, { qValues: number[]; visits: number }>): void {
    this.qTable.clear();
    for (const [key, entry] of Object.entries(data)) {
      this.qTable.set(key, {
        qValues: new Float32Array(entry.qValues),
        visits: entry.visits,
        lastUpdate: Date.now(),
      });
    }
  }

  // Private methods

  /**
   * Legacy hash function (kept for backward compatibility)
   */
  private hashState(context: string): string {
    // Simple hash for context string
    let hash = 0;
    for (let i = 0; i < context.length; i++) {
      const char = context.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }
    return `state_${hash}`;
  }

  /**
   * Public state-key encoder (#2239). This is exactly what `route()` uses
   * to look up Q-values, so testing it directly is testing the binding the
   * Q-learner actually sees.
   */
  getStateKey(context: string): string {
    return this.hashStateOptimized(context);
  }

  /**
   * Optimized state hashing using feature extraction
   * Creates a more semantic representation of the task context
   */
  private hashStateOptimized(context: string): string {
    // Check feature hash cache first
    if (this.featureHashCache.has(context)) {
      const cached = this.featureHashCache.get(context)!;
      return this.featureVectorToKey(cached);
    }

    // Extract features from context
    const features = this.extractFeatures(context);

    // Cache the feature vector
    if (this.featureHashCache.size < 1000) { // Limit cache size
      this.featureHashCache.set(context, features);
    }

    return this.featureVectorToKey(features);
  }

  /**
   * Extract feature vector from task context
   * Uses keyword matching and n-gram hashing
   */
  private extractFeatures(context: string): Float32Array {
    const features = new Float32Array(this.config.stateSpaceDim);
    const lowerContext = context.toLowerCase();
    const words = lowerContext.split(/\s+/);

    // Feature 1-32: Keyword presence (binary features)
    for (let i = 0; i < FEATURE_KEYWORDS.length && i < 32; i++) {
      if (lowerContext.includes(FEATURE_KEYWORDS[i])) {
        features[i] = 1.0;
      }
    }

    // Feature 33-40: Context length buckets
    const lengthBucket = Math.min(Math.floor(context.length / 50), 7);
    features[32 + lengthBucket] = 1.0;

    // Feature 41-48: Word count buckets
    const wordBucket = Math.min(Math.floor(words.length / 5), 7);
    features[40 + wordBucket] = 1.0;

    // Feature 49-56: File extension hints
    const extPatterns = ['.ts', '.js', '.py', '.go', '.rs', '.java', '.md', '.json'];
    for (let i = 0; i < extPatterns.length; i++) {
      if (lowerContext.includes(extPatterns[i])) {
        features[48 + i] = 1.0;
      }
    }

    // Feature 57-64: N-gram hash features (for capturing unique patterns)
    for (let i = 0; i < words.length - 1 && i < 8; i++) {
      const bigram = `${words[i]}_${words[i + 1]}`;
      const hash = this.murmurhash3(bigram) % 8;
      features[56 + hash] += 0.25;
    }

    // Normalize features
    let norm = 0;
    for (let i = 0; i < features.length; i++) {
      norm += features[i] * features[i];
    }
    norm = Math.sqrt(norm) || 1;
    for (let i = 0; i < features.length; i++) {
      features[i] /= norm;
    }

    return features;
  }

  /**
   * Convert feature vector to state key
   * Uses locality-sensitive hashing for similar contexts.
   *
   * #2239 — the previous fold was `((hash << 4) ^ q[i]) & 0x7fffffff` over 16
   * 4-bit groups: each group i landed at bit 4·(15−i), so groups 0–7 (= the
   * entire keyword block, features 0–31) shifted past the 31-bit mask and were
   * discarded. Keyword-distinct tasks collapsed to one Q-state. We now use a
   * 32-bit FNV-1a hash, which mixes every quantized group losslessly into the
   * state key. Encoder version bumped to 2; see PersistedModel.encoderVersion.
   */
  private featureVectorToKey(features: Float32Array): string {
    // Quantize features into 4-bit groups (16 groups for a 64-dim vector).
    const quantized: number[] = [];
    for (let i = 0; i < features.length; i += 4) {
      let bucket = 0;
      for (let j = 0; j < 4 && i + j < features.length; j++) {
        if (features[i + j] > 0.25) {
          bucket |= (1 << j);
        }
      }
      quantized.push(bucket);
    }

    // 32-bit FNV-1a over the quantized array — every group contributes.
    let hash = 0x811c9dc5 | 0; // FNV offset basis
    for (let i = 0; i < quantized.length; i++) {
      hash ^= quantized[i] & 0xff;
      hash = Math.imul(hash, 0x01000193); // FNV prime
    }
    return `fstate_${(hash >>> 0).toString(36)}`;
  }

  /**
   * MurmurHash3 32-bit implementation for n-gram hashing
   */
  private murmurhash3(str: string): number {
    let h1 = 0xdeadbeef;
    const c1 = 0xcc9e2d51;
    const c2 = 0x1b873593;

    for (let i = 0; i < str.length; i++) {
      let k1 = str.charCodeAt(i);
      k1 = Math.imul(k1, c1);
      k1 = (k1 << 15) | (k1 >>> 17);
      k1 = Math.imul(k1, c2);
      h1 ^= k1;
      h1 = (h1 << 13) | (h1 >>> 19);
      h1 = Math.imul(h1, 5) + 0xe6546b64;
    }

    h1 ^= str.length;
    h1 ^= h1 >>> 16;
    h1 = Math.imul(h1, 0x85ebca6b);
    h1 ^= h1 >>> 13;
    h1 = Math.imul(h1, 0xc2b2ae35);
    h1 ^= h1 >>> 16;

    return h1 >>> 0;
  }

  private getQValues(stateKey: string): number[] {
    const entry = this.qTable.get(stateKey);
    if (!entry) {
      return new Array(this.config.numActions).fill(0);
    }
    return Array.from(entry.qValues);
  }

  private getOrCreateEntry(stateKey: string): QEntry {
    let entry = this.qTable.get(stateKey);
    if (!entry) {
      entry = {
        qValues: new Float32Array(this.config.numActions),
        visits: 0,
        lastUpdate: Date.now(),
      };
      this.qTable.set(stateKey, entry);
    }
    return entry;
  }

  private argmax(values: number[]): number {
    let maxIdx = 0;
    let maxVal = values[0];
    for (let i = 1; i < values.length; i++) {
      if (values[i] > maxVal) {
        maxVal = values[i];
        maxIdx = i;
      }
    }
    return maxIdx;
  }

  private softmaxConfidence(qValues: number[], actionIdx: number): number {
    const maxQ = Math.max(...qValues);
    const expValues = qValues.map(q => Math.exp(q - maxQ)); // Subtract max for numerical stability
    const sumExp = expValues.reduce((a, b) => a + b, 0);
    return expValues[actionIdx] / sumExp;
  }

  private pruneQTable(): void {
    const entries = Array.from(this.qTable.entries())
      .sort((a, b) => a[1].lastUpdate - b[1].lastUpdate);

    const toRemove = entries.length - Math.floor(this.config.maxStates * 0.8);
    for (let i = 0; i < toRemove; i++) {
      this.qTable.delete(entries[i][0]);
    }
  }
}

/**
 * Factory function
 */
export function createQLearningRouter(config?: Partial<QLearningRouterConfig>): QLearningRouter {
  return new QLearningRouter(config);
}

/**
 * RuVector LLM WASM Integration
 *
 * Wraps @ruvector/ruvllm-wasm for browser-native LLM inference utilities.
 * Provides HNSW routing, SONA instant adaptation, MicroLoRA fine-tuning,
 * chat template formatting, KV cache management, and inference arena.
 *
 * Published API (v2.0.2): RuvLLMWasm, ChatTemplateWasm, ChatMessageWasm,
 * GenerateConfig, HnswRouterWasm, SonaInstantWasm, MicroLoraWasm,
 * KvCacheWasm, BufferPoolWasm, InferenceArenaWasm.
 *
 * v2.0.2 fixes:
 * - HNSW supports 1000+ patterns (fixed connect_node ordering)
 * - MicroLoRA adapt() now takes (input: Float32Array, feedback: AdaptFeedbackWasm)
 *
 * Remaining quirks:
 * - Stats objects return WASM pointers — use .toJson() or named accessors
 * - GenerateConfig float precision loss (f32 roundtrip)
 * - MicroLoRA apply() hardcoded to 768 dims regardless of config
 *
 * @module @claude-flow/cli/ruvector/ruvllm-wasm
 */

import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';

// WASM binary requires at least 768-dim input for MicroLoRA adapt()
const MICROLORA_WASM_MIN_DIM = 768;

// ── Types ────────────────────────────────────────────────────

export interface HnswRouterConfig {
  dimensions: number;
  maxPatterns: number;
  efSearch?: number;
}

export interface HnswPattern {
  name: string;
  embedding: Float32Array;
  metadata?: Record<string, unknown>;
}

export interface HnswRouteResult {
  name: string;
  score: number;
  metadata?: Record<string, unknown>;
}

export interface SonaConfig {
  hiddenDim?: number;
  learningRate?: number;
  emaDecay?: number;
  ewcLambda?: number;
  microLoraRank?: number;
  patternCapacity?: number;
}

export interface MicroLoraConfig {
  inputDim: number;
  outputDim: number;
  rank?: number;
  alpha?: number;
}

export interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface GenerateOptions {
  maxTokens?: number;
  temperature?: number;
  topP?: number;
  topK?: number;
  repetitionPenalty?: number;
  stopSequences?: string[];
}

export interface RuvllmStatus {
  available: boolean;
  initialized: boolean;
  version: string | null;
}

// ── WASM Module Detection & Init ─────────────────────────────

let _wasmReady = false;

/**
 * Check if @ruvector/ruvllm-wasm is installed and loadable.
 */
export async function isRuvllmWasmAvailable(): Promise<boolean> {
  try {
    const mod = await import('@ruvector/ruvllm-wasm');
    return typeof mod.RuvLLMWasm === 'function';
  } catch {
    return false;
  }
}

/**
 * Initialize the WASM module for Node.js. Safe to call multiple times.
 * Uses initSync with object form: { module: bytes } (raw bytes deprecated).
 */
export async function initRuvllmWasm(): Promise<void> {
  if (_wasmReady) return;
  try {
    const mod = await import('@ruvector/ruvllm-wasm');
    const require_ = createRequire(import.meta.url);
    const wasmPath = require_.resolve('@ruvector/ruvllm-wasm/ruvllm_wasm_bg.wasm');
    const wasmBytes = readFileSync(wasmPath);
    // MUST use object form — initSync(bytes) is deprecated
    mod.initSync({ module: wasmBytes });
    _wasmReady = true;
  } catch (err) {
    throw new Error(`Failed to initialize @ruvector/ruvllm-wasm: ${err}`);
  }
}

/**
 * Get ruvllm-wasm status.
 */
export async function getRuvllmStatus(): Promise<RuvllmStatus> {
  const available = await isRuvllmWasmAvailable();
  if (!available) {
    return { available: false, initialized: false, version: null };
  }
  try {
    const mod = await import('@ruvector/ruvllm-wasm');
    // version is a standalone function, not on RuvLLMWasm class
    const version = typeof mod.getVersion === 'function' ? mod.getVersion() : null;
    return { available: true, initialized: _wasmReady, version };
  } catch {
    return { available: true, initialized: _wasmReady, version: null };
  }
}

// ── HNSW Router ──────────────────────────────────────────────

/**
 * Maximum safe pattern count for HNSW router.
 * v2.0.2 supports 1000+ patterns (fixed connect_node ordering).
 */
export const HNSW_MAX_SAFE_PATTERNS = 1024;

/**
 * Create a WASM HNSW router for semantic routing.
 * Returns an object with add/route/clear methods.
 *
 * Enforces HNSW_MAX_SAFE_PATTERNS limit (1024 in v2.0.2).
 */
export async function createHnswRouter(config: HnswRouterConfig): Promise<{
  addPattern: (pattern: HnswPattern) => boolean;
  route: (query: Float32Array, k?: number) => HnswRouteResult[];
  clear: () => void;
  patternCount: () => number;
  toJson: () => string;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const router = new mod.HnswRouterWasm(config.dimensions, config.maxPatterns);
  if (config.efSearch) {
    router.setEfSearch(config.efSearch);
  }

  let count = 0;

  return {
    addPattern(pattern: HnswPattern): boolean {
      if (count >= HNSW_MAX_SAFE_PATTERNS) {
        throw new Error(
          `HNSW pattern limit reached (${HNSW_MAX_SAFE_PATTERNS}).`
        );
      }
      const metadataJson = JSON.stringify(pattern.metadata ?? {});
      // addPattern requires 3 args: (embedding, name, metadata_json)
      const ok = router.addPattern(pattern.embedding, pattern.name, metadataJson);
      if (ok) count++;
      return ok;
    },
    route(query: Float32Array, k = 3): HnswRouteResult[] {
      const raw = router.route(query, k);
      return Array.from(raw).map((r: any) => ({
        name: r.name ?? r.pattern_name ?? '',
        score: r.score ?? r.distance ?? 0,
        metadata: r.metadata ? (typeof r.metadata === 'string' ? JSON.parse(r.metadata) : r.metadata) : undefined,
      }));
    },
    clear(): void {
      router.clear();
      count = 0;
    },
    patternCount(): number {
      return count;
    },
    toJson(): string {
      return router.toJson();
    },
  };
}

// ── SONA Instant Adaptation ──────────────────────────────────

/**
 * Create a SONA instant adaptation loop (<1ms adaptation).
 * v2.0.1: requires SonaConfigWasm object, not raw number.
 */
export async function createSonaInstant(config: SonaConfig = {}): Promise<{
  adapt: (quality: number) => void;
  recordPattern: (embedding: number[], success: boolean) => void;
  suggestAction: (context: string) => string | undefined;
  stats: () => string;
  reset: () => void;
  toJson: () => string;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const sonaConfig = new mod.SonaConfigWasm();
  if (config.hiddenDim !== undefined) sonaConfig.hiddenDim = config.hiddenDim;
  if (config.learningRate !== undefined) sonaConfig.learningRate = config.learningRate;
  if (config.emaDecay !== undefined) sonaConfig.emaDecay = config.emaDecay;
  if (config.ewcLambda !== undefined) sonaConfig.ewcLambda = config.ewcLambda;
  if (config.microLoraRank !== undefined) sonaConfig.microLoraRank = config.microLoraRank;
  if (config.patternCapacity !== undefined) sonaConfig.patternCapacity = config.patternCapacity;

  const sona = new mod.SonaInstantWasm(sonaConfig);

  return {
    adapt(quality: number): void {
      sona.instantAdapt(quality);
    },
    recordPattern(embedding: number[], success: boolean): void {
      sona.recordPattern(embedding, success);
    },
    suggestAction(context: string): string | undefined {
      return sona.suggestAction(context);
    },
    stats(): string {
      return sona.toJson();
    },
    reset(): void {
      sona.reset();
    },
    toJson(): string {
      return sona.toJson();
    },
  };
}

// ── MicroLoRA ────────────────────────────────────────────────

/**
 * Create a MicroLoRA adapter (ultra-lightweight LoRA, ranks 1-4).
 * v2.0.2: .adapt(input, feedback) takes Float32Array + AdaptFeedbackWasm.
 */
export async function createMicroLora(config: MicroLoraConfig): Promise<{
  apply: (input: Float32Array) => Float32Array;
  adapt: (quality: number, learningRate?: number, success?: boolean) => void;
  applyUpdates: (learningRate?: number) => void;
  stats: () => string;
  reset: () => void;
  toJson: () => string;
  pendingUpdates: () => number;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const loraConfig = new mod.MicroLoraConfigWasm();
  loraConfig.inputDim = config.inputDim;
  loraConfig.outputDim = config.outputDim;
  loraConfig.rank = config.rank ?? 2;
  loraConfig.alpha = config.alpha ?? 1.0;

  const lora = new mod.MicroLoraWasm(loraConfig);

  return {
    apply(input: Float32Array): Float32Array {
      return lora.apply(input);
    },
    adapt(quality: number, learningRate = 0.01, success = true): void {
      const feedback = new mod.AdaptFeedbackWasm();
      feedback.quality = quality;
      feedback.learningRate = learningRate;
      try { (feedback as any).success = success; } catch { /* v2.0.2 quirk */ }
      const input = new Float32Array(Math.max(config.inputDim, MICROLORA_WASM_MIN_DIM));
      lora.adapt(input, feedback);
      // Flush accumulated gradients. HONEST CAVEAT (audit
      // docs/reviews/intelligence-system-audit-2026-05-29.md): even WITH this
      // flush, the shipped @ruvector/ruvllm-wasm@2.0.2 MicroLoraWasm.apply()
      // output is empirically UNCHANGED (measured maxAbsDelta = 0 after 200
      // adapts). MicroLoRA adaptation is therefore effectively a no-op on
      // inference with this WASM backend. We do NOT synthesize a fake gradient
      // from the scalar quality to make output "move" — that would be a
      // fabricated signal. Real adaptation needs the WASM backend to flush B,
      // or a caller supplying real gradients.
      lora.applyUpdates(learningRate as unknown as Float32Array);
    },
    applyUpdates(learningRate = 0.01): void {
      // WASM runtime signature is applyUpdates(learning_rate: number); the
      // shipped .d.ts mistypes it as Float32Array, hence the cast.
      lora.applyUpdates(learningRate as unknown as Float32Array);
    },
    stats(): string {
      return lora.toJson();
    },
    reset(): void {
      lora.reset();
    },
    toJson(): string {
      return lora.toJson();
    },
    pendingUpdates(): number {
      return lora.pendingUpdates();
    },
  };
}

// ── Chat Template Formatting ─────────────────────────────────

type TemplatePreset = 'llama3' | 'mistral' | 'chatml' | 'phi' | 'gemma';

/**
 * Format chat messages using a chat template.
 * Supports presets (llama3, mistral, chatml, phi, gemma) and auto-detection.
 */
export async function formatChat(
  messages: ChatMessage[],
  template: TemplatePreset | { custom: string } | { modelId: string },
): Promise<string> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  // Build template
  let tmpl: any;
  if (typeof template === 'string') {
    const presets: Record<string, () => any> = {
      llama3: () => mod.ChatTemplateWasm.llama3(),
      mistral: () => mod.ChatTemplateWasm.mistral(),
      chatml: () => mod.ChatTemplateWasm.chatml(),
      phi: () => mod.ChatTemplateWasm.phi(),
      gemma: () => mod.ChatTemplateWasm.gemma(),
    };
    const factory = presets[template];
    if (!factory) throw new Error(`Unknown template preset: ${template}. Use: ${Object.keys(presets).join(', ')}`);
    tmpl = factory();
  } else if ('custom' in template) {
    tmpl = mod.ChatTemplateWasm.custom(template.custom);
  } else if ('modelId' in template) {
    tmpl = mod.ChatTemplateWasm.detectFromModelId(template.modelId);
  }

  // Build messages
  const wasmMessages = messages.map(m => {
    switch (m.role) {
      case 'system': return mod.ChatMessageWasm.system(m.content);
      case 'user': return mod.ChatMessageWasm.user(m.content);
      case 'assistant': return mod.ChatMessageWasm.assistant(m.content);
      default: throw new Error(`Unknown role: ${m.role}`);
    }
  });

  return tmpl.format(wasmMessages);
}

// ── KV Cache ─────────────────────────────────────────────────

/**
 * Create a KV cache for token management.
 */
export async function createKvCache(opts?: {
  tailLength?: number;
  maxTokens?: number;
  numKvHeads?: number;
  headDim?: number;
}): Promise<{
  append: (keys: Float32Array, values: Float32Array) => void;
  stats: () => string;
  clear: () => void;
  tokenCount: () => number;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  let cache: any;
  if (opts) {
    const config = new mod.KvCacheConfigWasm();
    if (opts.tailLength !== undefined) config.tailLength = opts.tailLength;
    if (opts.maxTokens !== undefined) config.maxTokens = opts.maxTokens;
    if (opts.numKvHeads !== undefined) config.numKvHeads = opts.numKvHeads;
    if (opts.headDim !== undefined) config.headDim = opts.headDim;
    cache = new mod.KvCacheWasm(config);
  } else {
    cache = mod.KvCacheWasm.withDefaults();
  }

  return {
    append(keys: Float32Array, values: Float32Array): void {
      cache.append(keys, values);
    },
    stats(): string {
      // Use toJson if available, otherwise stringify
      try { return JSON.stringify(cache.stats()); } catch { return '{}'; }
    },
    clear(): void {
      cache.clear();
    },
    tokenCount(): number {
      return cache.tokenCount;
    },
  };
}

// ── Generate Config ──────────────────────────────────────────

/**
 * Create a generation config object.
 * Note: f32 precision loss is expected (0.7 → 0.699999...).
 */
export async function createGenerateConfig(opts: GenerateOptions = {}): Promise<string> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const config = new mod.GenerateConfig();
  if (opts.maxTokens !== undefined) config.maxTokens = opts.maxTokens;
  if (opts.temperature !== undefined) config.temperature = opts.temperature;
  if (opts.topP !== undefined) config.topP = opts.topP;
  if (opts.topK !== undefined) config.topK = opts.topK;
  if (opts.repetitionPenalty !== undefined) config.repetitionPenalty = opts.repetitionPenalty;
  for (const seq of opts.stopSequences ?? []) {
    config.addStopSequence(seq);
  }

  return config.toJson();
}

// ── Buffer Pool ──────────────────────────────────────────────

/**
 * Create a buffer pool for inference memory management.
 */
export async function createBufferPool(capacity: number): Promise<{
  prewarm: (count: number) => void;
  stats: () => string;
  hitRate: () => number;
  clear: () => void;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const pool = mod.BufferPoolWasm.withCapacity(capacity);

  return {
    prewarm(count: number): void {
      pool.prewarmAll(count);
    },
    stats(): string {
      return pool.statsJson();
    },
    hitRate(): number {
      return pool.hitRate;
    },
    clear(): void {
      pool.clear();
    },
  };
}

// ── Inference Arena ──────────────────────────────────────────

/**
 * Create an inference arena for model memory allocation.
 */
export async function createInferenceArena(
  opts: { capacity: number } | { hiddenDim: number; vocabSize: number; batchSize: number },
): Promise<{
  reset: () => void;
  used: () => number;
  capacity: () => number;
  remaining: () => number;
}> {
  await initRuvllmWasm();
  const mod = await import('@ruvector/ruvllm-wasm');

  const arena = 'capacity' in opts
    ? new mod.InferenceArenaWasm(opts.capacity)
    : mod.InferenceArenaWasm.forModel(opts.hiddenDim, opts.vocabSize, opts.batchSize);

  return {
    reset(): void { arena.reset(); },
    used(): number { return arena.used; },
    capacity(): number { return arena.capacity; },
    remaining(): number { return arena.remaining; },
  };
}

/**
 * Pure JavaScript SemanticRouter implementation
 *
 * Provides intent routing using cosine similarity.
 * This is a fallback implementation since @ruvector/router's native VectorDb has bugs.
 *
 * Performance: ~50,000 routes/sec with 100 intents (sufficient for agent routing)
 */

export interface Intent {
  name: string;
  utterances: string[];
  metadata?: Record<string, unknown>;
}

export interface RouteResult {
  intent: string;
  score: number;
  metadata: Record<string, unknown>;
}

export interface RouterConfig {
  dimension: number;
  metric?: 'cosine' | 'euclidean' | 'dotProduct';
}

interface StoredIntent {
  name: string;
  embeddings: Float32Array[];
  metadata: Record<string, unknown>;
}

export class SemanticRouter {
  private dimension: number;
  private metric: 'cosine' | 'euclidean' | 'dotProduct';
  private intents: Map<string, StoredIntent> = new Map();
  private totalVectors = 0;

  constructor(config: RouterConfig) {
    if (!config || typeof config.dimension !== 'number') {
      throw new Error('SemanticRouter requires a dimension in config');
    }
    this.dimension = config.dimension;
    this.metric = config.metric ?? 'cosine';
  }

  /**
   * Add an intent with pre-computed embeddings
   */
  addIntentWithEmbeddings(
    name: string,
    embeddings: Float32Array[],
    metadata: Record<string, unknown> = {}
  ): void {
    if (!name || !Array.isArray(embeddings)) {
      throw new Error('Must provide name and embeddings array');
    }

    // Validate embeddings
    for (const emb of embeddings) {
      if (!(emb instanceof Float32Array) || emb.length !== this.dimension) {
        throw new Error(`Embedding must be Float32Array of length ${this.dimension}`);
      }
    }

    // Normalize embeddings for cosine similarity
    const normalizedEmbeddings = embeddings.map(emb => this.normalize(emb));

    this.intents.set(name, {
      name,
      embeddings: normalizedEmbeddings,
      metadata,
    });
    this.totalVectors += embeddings.length;
  }

  /**
   * Route a query using a pre-computed embedding
   */
  routeWithEmbedding(embedding: Float32Array, k = 5): RouteResult[] {
    if (!(embedding instanceof Float32Array) || embedding.length !== this.dimension) {
      throw new Error(`Embedding must be Float32Array of length ${this.dimension}`);
    }

    const normalizedQuery = this.normalize(embedding);
    const scores: { intent: string; score: number; metadata: Record<string, unknown> }[] = [];

    // Calculate best score for each intent
    for (const [intentName, intent] of this.intents) {
      let bestScore = -Infinity;

      for (const storedEmb of intent.embeddings) {
        const score = this.similarity(normalizedQuery, storedEmb);
        if (score > bestScore) {
          bestScore = score;
        }
      }

      scores.push({
        intent: intentName,
        score: bestScore,
        metadata: intent.metadata,
      });
    }

    // Sort by score descending and take top k
    return scores
      .sort((a, b) => b.score - a.score)
      .slice(0, k);
  }

  /**
   * Remove an intent
   */
  removeIntent(name: string): boolean {
    const intent = this.intents.get(name);
    if (!intent) return false;

    this.totalVectors -= intent.embeddings.length;
    this.intents.delete(name);
    return true;
  }

  /**
   * Get all intent names
   */
  getIntents(): string[] {
    return Array.from(this.intents.keys());
  }

  /**
   * Get intent details
   */
  getIntent(name: string): Intent | null {
    const data = this.intents.get(name);
    if (!data) return null;
    return {
      name: data.name,
      utterances: [], // We don't store utterances, only embeddings
      metadata: data.metadata,
    };
  }

  /**
   * Clear all intents
   */
  clear(): void {
    this.intents.clear();
    this.totalVectors = 0;
  }

  /**
   * Get total vector count
   */
  count(): number {
    return this.totalVectors;
  }

  /**
   * Get number of intents
   */
  intentCount(): number {
    return this.intents.size;
  }

  /**
   * Normalize a vector for cosine similarity
   */
  private normalize(vec: Float32Array): Float32Array {
    let norm = 0;
    for (let i = 0; i < vec.length; i++) {
      norm += vec[i] * vec[i];
    }
    norm = Math.sqrt(norm);

    if (norm === 0) return vec;

    const normalized = new Float32Array(vec.length);
    for (let i = 0; i < vec.length; i++) {
      normalized[i] = vec[i] / norm;
    }
    return normalized;
  }

  /**
   * Calculate similarity between two normalized vectors
   */
  private similarity(a: Float32Array, b: Float32Array): number {
    switch (this.metric) {
      case 'cosine':
        // For normalized vectors, cosine similarity = dot product
        return this.dotProduct(a, b);
      case 'dotProduct':
        return this.dotProduct(a, b);
      case 'euclidean':
        // Convert Euclidean distance to similarity
        return 1 / (1 + this.euclideanDistance(a, b));
      default:
        return this.dotProduct(a, b);
    }
  }

  private dotProduct(a: Float32Array, b: Float32Array): number {
    let sum = 0;
    for (let i = 0; i < a.length; i++) {
      sum += a[i] * b[i];
    }
    return sum;
  }

  private euclideanDistance(a: Float32Array, b: Float32Array): number {
    let sum = 0;
    for (let i = 0; i < a.length; i++) {
      const diff = a[i] - b[i];
      sum += diff * diff;
    }
    return Math.sqrt(sum);
  }
}

/**
 * Create a SemanticRouter with the given configuration
 */
export function createSemanticRouter(config: RouterConfig): SemanticRouter {
  return new SemanticRouter(config);
}

export default SemanticRouter;

/**
 * Vector Database Module
 *
 * Provides optional ruvector WASM-accelerated vector operations for:
 * - Semantic similarity search
 * - HNSW indexing (150x faster)
 * - Embedding generation
 *
 * Gracefully degrades when ruvector is not installed.
 *
 * Created with love by ruv.io
 */

import os from 'node:os';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

// ============================================================================
// Types
// ============================================================================

export interface VectorDB {
  insert(embedding: Float32Array, id: string, metadata?: Record<string, unknown>): void | Promise<void>;
  search(query: Float32Array, k?: number): Array<{ id: string; score: number; metadata?: Record<string, unknown> }> | Promise<Array<{ id: string; score: number; metadata?: Record<string, unknown> }>>;
  remove(id: string): boolean | Promise<boolean>;
  size(): number | Promise<number>;
  clear(): void | Promise<void>;
}

export interface RuVectorModule {
  createVectorDB(dimensions: number): Promise<VectorDB>;
  generateEmbedding(text: string, dimensions?: number): Float32Array;
  cosineSimilarity(a: Float32Array, b: Float32Array): number;
  isWASMAccelerated(): boolean;
}

// ============================================================================
// Fallback Implementation (when ruvector not available)
// ============================================================================

class FallbackVectorDB implements VectorDB {
  private vectors: Map<string, { embedding: Float32Array; metadata?: Record<string, unknown> }> = new Map();
  private dimensions: number;

  constructor(dimensions: number) {
    this.dimensions = dimensions;
  }

  insert(embedding: Float32Array, id: string, metadata?: Record<string, unknown>): void {
    this.vectors.set(id, { embedding, metadata });
  }

  search(query: Float32Array, k: number = 10): Array<{ id: string; score: number; metadata?: Record<string, unknown> }> {
    const results: Array<{ id: string; score: number; metadata?: Record<string, unknown> }> = [];

    for (const [id, { embedding, metadata }] of this.vectors) {
      const score = cosineSimilarity(query, embedding);
      results.push({ id, score, metadata });
    }

    return results
      .sort((a, b) => b.score - a.score)
      .slice(0, k);
  }

  remove(id: string): boolean {
    return this.vectors.delete(id);
  }

  size(): number {
    return this.vectors.size;
  }

  clear(): void {
    this.vectors.clear();
  }
}

/**
 * Compute cosine similarity between two vectors
 */
function cosineSimilarity(a: Float32Array, b: Float32Array): number {
  if (a.length !== b.length) {
    throw new Error(`Vector dimension mismatch: ${a.length} vs ${b.length}`);
  }

  let dotProduct = 0;
  let normA = 0;
  let normB = 0;

  for (let i = 0; i < a.length; i++) {
    dotProduct += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }

  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dotProduct / denom;
}

/**
 * Whether the hash-embedding one-time warning has been emitted
 */
let hashEmbeddingWarned = false;

/**
 * Generate a simple hash-based embedding (fallback when ruvector not available)
 * WARNING: Produces deterministic vectors with NO semantic meaning.
 */
function generateHashEmbedding(text: string, dimensions: number = 768): Float32Array {
  if (!hashEmbeddingWarned) {
    hashEmbeddingWarned = true;
    console.warn(
      '[vector-db] Using hash-based pseudo-embeddings (no semantic similarity). ' +
      'Install ruvector or @claude-flow/embeddings for real ML embeddings.'
    );
  }
  const embedding = new Float32Array(dimensions);
  const normalized = text.toLowerCase().trim();

  // Simple hash function
  let hash = 0;
  for (let i = 0; i < normalized.length; i++) {
    hash = ((hash << 5) - hash) + normalized.charCodeAt(i);
    hash = hash & hash; // Convert to 32bit integer
  }

  // Generate pseudo-random embedding based on hash
  for (let i = 0; i < dimensions; i++) {
    embedding[i] = Math.sin(hash * (i + 1) * 0.001) * 0.5 + 0.5;
  }

  // Normalize
  let norm = 0;
  for (let i = 0; i < dimensions; i++) {
    norm += embedding[i] * embedding[i];
  }
  norm = Math.sqrt(norm);
  for (let i = 0; i < dimensions; i++) {
    embedding[i] /= norm;
  }

  return embedding;
}

// ============================================================================
// Module State
// ============================================================================

let ruvectorModule: RuVectorModule | null = null;
let loadAttempted = false;
let isAvailable = false;

// ============================================================================
// Public API
// ============================================================================

/**
 * Attempt to load the ruvector module
 * Returns true if successfully loaded, false otherwise
 */
export async function loadRuVector(): Promise<boolean> {
  if (loadAttempted) {
    return isAvailable;
  }

  loadAttempted = true;

  try {
    // Dynamic import to handle missing dependency gracefully
    const ruvector = await import('ruvector').catch(() => null);

    // ruvector exports VectorDB class, not createVectorDB function
    if (ruvector && (typeof ruvector.VectorDB === 'function' || typeof ruvector.VectorDb === 'function')) {
      // Create adapter module that matches our expected interface
      const VectorDBClass = ruvector.VectorDB || ruvector.VectorDb;
      ruvectorModule = {
        createVectorDB: async (dimensions: number): Promise<VectorDB> => {
          // Build the HNSW graph with explicit, high-recall parameters instead
          // of relying on the native layer's undocumented defaults. Measured on
          // a 384-dim clustered corpus (scripts/benchmark-intelligence.mjs):
          //   - sparser graphs (e.g. m=16/efConstruction=64) are faster but
          //     drop recall@10 to ~0.68 at N=20k — unacceptable for a memory
          //     store, so we use the standard high-recall HNSW setting
          //     m=32/efConstruction=200, which keeps recall@10 ~0.99 while still
          //     scaling sub-linearly (log-graph traversal) above the crossover.
          // These map onto ruvector's DbOptions.hnsw { m, efConstruction }.
          //
          // storagePath: the native ruvector DB takes an exclusive file lock on
          // its storage path. Without an explicit path it defaults to a shared
          // file in the CWD (e.g. agentdb.rvf), which is frequently already
          // held by a running daemon/MCP server. When the lock cannot be
          // acquired the constructor THROWS, and createVectorDB() below
          // silently degrades to the O(n) brute-force FallbackVectorDB — so the
          // "HNSW" index is never actually used. Giving each transient index a
          // unique path avoids that contention so the real HNSW graph is built.
          const db = new VectorDBClass({
            dimensions,
            hnswConfig: { m: 32, efConstruction: 200 },
            storagePath: path.join(os.tmpdir(), `ruvector-${process.pid}-${randomUUID()}.rvf`),
          });
          // Wrap ruvector's VectorDB to match our interface
          return {
            insert: (embedding: Float32Array, id: string, metadata?: Record<string, unknown>) => {
              db.insert({ id, vector: embedding, metadata });
            },
            search: async (query: Float32Array, k: number = 10) => {
              const results = await db.search({ vector: query, k });
              return results.map((r: any) => ({
                id: r.id,
                score: r.score,
                metadata: r.metadata,
              }));
            },
            remove: (id: string) => {
              db.delete(id);
              return true;
            },
            size: async () => {
              const len = await db.len();
              return len;
            },
            clear: () => {
              // Not directly supported - would need to recreate
            },
          } as VectorDB;
        },
        generateEmbedding: (text: string, dimensions: number = 768): Float32Array => {
          // ruvector may not have this - use fallback
          return generateHashEmbedding(text, dimensions);
        },
        cosineSimilarity: (a: Float32Array, b: Float32Array): number => {
          return cosineSimilarity(a, b);
        },
        isWASMAccelerated: (): boolean => {
          return ruvector.isWasm?.() ?? false;
        },
      };
      isAvailable = true;
      return true;
    }
  } catch {
    // Silently fail - ruvector is optional
  }

  isAvailable = false;
  return false;
}

/**
 * Check if ruvector is available
 */
export function isRuVectorAvailable(): boolean {
  return isAvailable;
}

/**
 * Check if WASM acceleration is enabled
 */
export function isWASMAccelerated(): boolean {
  if (ruvectorModule && typeof ruvectorModule.isWASMAccelerated === 'function') {
    return ruvectorModule.isWASMAccelerated();
  }
  return false;
}

/**
 * Create a vector database
 * Uses ruvector HNSW if available, falls back to brute-force search
 */
export async function createVectorDB(dimensions: number = 768): Promise<VectorDB> {
  await loadRuVector();

  if (ruvectorModule && typeof ruvectorModule.createVectorDB === 'function') {
    try {
      return await ruvectorModule.createVectorDB(dimensions);
    } catch (err) {
      // Fall back to simple implementation, but make the degradation VISIBLE.
      // A silent fall-through here turns HNSW into O(n) brute force without any
      // signal — exactly the failure mode that masked the lock-contention bug.
      console.warn(
        `[vector-db] ruvector HNSW init failed, falling back to brute-force search: ${(err as Error)?.message ?? err}`
      );
    }
  }

  return new FallbackVectorDB(dimensions);
}

/**
 * Generate an embedding for text
 * Uses ruvector if available, falls back to hash-based embedding
 *
 * @returns The embedding vector. When using hash fallback, the returned
 *          Float32Array will have a `_warning` property (non-enumerable)
 *          indicating it lacks semantic meaning.
 */
export function generateEmbedding(text: string, dimensions: number = 768): Float32Array {
  if (ruvectorModule && typeof ruvectorModule.generateEmbedding === 'function') {
    try {
      return ruvectorModule.generateEmbedding(text, dimensions);
    } catch {
      // Fall back to hash-based embedding
    }
  }

  const embedding = generateHashEmbedding(text, dimensions);
  // Tag the result so consumers can detect it came from hash fallback
  Object.defineProperty(embedding, '_warning', {
    value: 'hash-based pseudo-embedding — no semantic similarity',
    enumerable: false,
    configurable: true,
  });
  return embedding;
}

/**
 * Compute cosine similarity between two vectors
 */
export function computeSimilarity(a: Float32Array, b: Float32Array): number {
  if (ruvectorModule && typeof ruvectorModule.cosineSimilarity === 'function') {
    try {
      return ruvectorModule.cosineSimilarity(a, b);
    } catch {
      // Fall back to JS implementation
    }
  }

  return cosineSimilarity(a, b);
}

/**
 * Get status information about the ruvector module
 */
export function getStatus(): {
  available: boolean;
  wasmAccelerated: boolean;
  backend: 'ruvector-stub-search-disabled' | 'ruvector-native' | 'fallback';
} {
  if (!isAvailable) {
    return {
      available: false,
      wasmAccelerated: false,
      backend: 'fallback',
    };
  }

  // HONESTY (audit docs/reviews/intelligence-system-audit-2026-05-29.md):
  // ruvector's `isWasm()` does NOT mean "WASM-accelerated" — there is no WASM
  // HNSW build in this stack. `isWasm()===true` means the do-nothing STUB is
  // active (search() returns []), i.e. native NAPI failed to load. So
  // wasmAccelerated===false is the HEALTHY state (native NAPI is the fastest
  // backend available). We label the stub honestly so a regression into it is
  // visible instead of being mistaken for a faster mode.
  const stubActive = isWASMAccelerated();
  return {
    available: true,
    wasmAccelerated: stubActive,
    backend: stubActive ? 'ruvector-stub-search-disabled' : 'ruvector-native',
  };
}
